// Verse text, keyed by reference id.
var verses = {
    "2CO.5.17": "Siis, jos joku on Kristuksessa, niin hän on uusi luomus; se, mikä on vanhaa, on kadonnut, katso, uusi on sijaan tullut.",
    "COL.3.1-2": "Jos te siis olette herätetyt Kristuksen kanssa, niin etsikää sitä, mikä on ylhäällä, jossa Kristus on, istuen Jumalan oikealla puolella. Olkoon mielenne siihen, mikä ylhäällä on, älköön siihen, mikä on maan päällä.",
    "ISA.43.2": "Jos vetten läpi kuljet, olen minä sinun kanssasi, jos virtojen läpi, eivät ne sinua upota; jos tulen läpi käyt, et sinä kärvenny, eikä liekki sinua polta.",
    "PSA.34.8": "Maistakaa ja katsokaa, kuinka Herra on hyvä. Autuas se mies, joka häneen turvaa!",
    "ROM.15.4": "Sillä kaikki, mikä ennen on kirjoitettu, on kirjoitettu meille opiksi, että meillä kärsivällisyyden ja Raamatun lohdutuksen kautta olisi toivo.",
    "PSA.55.22": "Heitä murheesi Herran huomaan, hän pitää sinusta huolen, ei hän salli vanhurskaan ikinä horjua.",
    "ISA.40.8": "Ruoho kuivuu, kukkanen lakastuu, mutta meidän Jumalamme sana pysyy iankaikkisesti.",
    "PSA.127.1": "Jos Herra ei huonetta rakenna, niin sen rakentajat turhaan vaivaa näkevät. Jos Herra ei kaupunkia varjele, niin turhaan vartija valvoo.",
    "ISA.53.6": "Me vaelsimme kaikki eksyksissä niinkuin lampaat, kukin meistä poikkesi omalle tielleen. Mutta Herra heitti hänen päällensä kaikkien meidän syntivelkamme.",
    "PSA.42.1-2": "Niinkuin peura halajaa vesipuroille, niin minun sieluni halajaa sinua, Jumala. Minun sieluni janoo Jumalaa, elävää Jumalaa. Milloin saan minä tulla Jumalan kasvojen eteen?",
    "2SA.22.31": "Jumalan tie on nuhteeton, Herran sana tulessa koeteltu. Hän on kaikkien kilpi, jotka häneen turvaavat.",
    "PSA.40.1-3": "Hartaasti minä odotin Herraa, ja hän kumartui minun puoleeni ja kuuli minun huutoni. Ja hän nosti minut ylös turmion kuopasta, lokaisesta liejusta, ja asetti minun jalkani kalliolle, hän vahvisti minun askeleeni. Hän antoi minun suuhuni uuden virren, kiitoslaulun Jumalallemme. Sen näkevät monet ja pelkäävät ja turvaavat Herraan.",
    "JOB.19.25": "Mutta minä tiedän lunastajani elävän, ja viimeisenä hän on seisova multien päällä.",
    "PSA.23.1-3": "Herra on minun paimeneni, ei minulta mitään puutu. Viheriäisille niityille hän vie minut lepäämään; virvoittavien vetten tykö hän minut johdattaa. Hän virvoittaa minun sieluni. Hän ohjaa minut oikealle tielle nimensä tähden.",
    "MAT.5.44": "Mutta minä sanon teille: rakastakaa vihollisianne ja rukoilkaa niiden puolesta, jotka teitä vainoavat,",
    "ISA.55.8-9": "Sillä minun ajatukseni eivät ole teidän ajatuksianne, eivätkä teidän tienne ole minun teitäni, sanoo Herra. Vaan niin paljon korkeampi kuin taivas on maata, ovat minun tieni korkeammat teidän teitänne ja minun ajatukseni teidän ajatuksianne.",
    "LUK.19.10": "sillä Ihmisen Poika on tullut etsimään ja pelastamaan sitä, mikä kadonnut on\".",
    "HEB.13.5-6": "Älkää olko vaelluksessanne ahneita; tyytykää siihen, mitä teillä on; sillä hän itse on sanonut: \"En minä sinua hylkää enkä sinua jätä\"; niin että me turvallisin mielin sanomme: \"Herra on minun auttajani, en minä pelkää; mitä voi ihminen minulle tehdä?\"",
    "1CH.29.11": "Sinun, Herra, on suuruus ja väkevyys ja loisto ja kunnia ja kirkkaus, sillä sinun on kaikki taivaassa ja maan päällä. Sinun, Herra, on valtakunta, ja sinä olet korotettu kaiken pääksi.",
    "HEB.13.20-21": "Mutta rauhan Jumala, joka on kuolleista nostanut hänet, joka iankaikkisen liiton veren kautta on se suuri lammasten paimen, meidän Herramme Jeesuksen, hän tehköön teidät kykeneviksi kaikkeen hyvään, voidaksenne toteuttaa hänen tahtonsa, ja vaikuttakoon teissä sen, mikä on hänelle otollista, Jeesuksen Kristuksen kautta; hänelle kunnia aina ja iankaikkisesti! Amen.",
    "1CO.1.18": "Sillä sana rististä on hullutus niille, jotka kadotukseen joutuvat, mutta meille, jotka pelastumme, se on Jumalan voima.",
    "MAT.5.14-16": "Te olette maailman valkeus. Ei voi ylhäällä vuorella oleva kaupunki olla kätkössä; eikä lamppua sytytetä ja panna vakan alle, vaan lampunjalkaan, ja niin se loistaa kaikille huoneessa oleville. Niin loistakoon teidän valonne ihmisten edessä, että he näkisivät teidän hyvät tekonne ja ylistäisivät teidän Isäänne, joka on taivaissa.",
    "COL.3.23-24": "Kaikki, mitä teette, se tehkää sydämestänne, niinkuin Herralle eikä ihmisille, tietäen, että te saatte Herralta palkaksi perinnön; te palvelette Herraa Kristusta.",
    "ROM.8.28": "Mutta me tiedämme, että kaikki yhdessä vaikuttaa niiden parhaaksi, jotka Jumalaa rakastavat, niiden, jotka hänen aivoituksensa mukaan ovat kutsutut.",
    "JHN.11.25-26": "Jeesus sanoi hänelle: \"Minä olen ylösnousemus ja elämä; joka uskoo minuun, se elää, vaikka olisi kuollut. Eikä yksikään, joka elää ja uskoo minuun, ikinä kuole. Uskotko sen?\"",
    "1CO.13.6-7": "ei iloitse vääryydestä, vaan iloitsee yhdessä totuuden kanssa; kaikki se peittää, kaikki se uskoo, kaikki se toivoo, kaikki se kärsii.",
    "MAT.7.12": "Sentähden, kaikki, mitä te tahdotte ihmisten teille tekevän, tehkää myös te samoin heille; sillä tämä on laki ja profeetat.",
    "PSA.91.11": "Sillä hän antaa enkeleilleen sinusta käskyn varjella sinua kaikilla teilläsi.",
    "ACT.2.38": "Niin Pietari sanoi heille: \"Tehkää parannus ja ottakoon kukin teistä kasteen Jeesuksen Kristuksen nimeen syntienne anteeksisaamiseksi, niin te saatte Pyhän Hengen lahjan.",
    "1CO.3.16": "Ettekö tiedä, että te olette Jumalan temppeli ja että Jumalan Henki asuu teissä?",
    "ROM.3.23-24": "Sillä kaikki ovat syntiä tehneet ja ovat Jumalan kirkkautta vailla ja saavat lahjaksi vanhurskauden hänen armostaan sen lunastuksen kautta, joka on Kristuksessa Jeesuksessa,",
    "MAT.5.6": "Autuaita ovat ne, jotka isoavat ja janoavat vanhurskautta, sillä heidät ravitaan.",
    "ISA.26.3": "Vakaamieliselle sinä talletat rauhan, rauhan, sillä hän turvaa sinuun.",
    "PRO.17.22": "Terveydeksi on iloinen sydän, mutta murtunut mieli kuivuttaa luut.",
    "NEH.8.10": "Ja hän sanoi vielä heille: \"Menkää ja syökää rasvaisia ruokia ja juokaa makeita juomia ja lähettäkää maistiaisia niille, joilla ei ole mitään valmistettuna, sillä tämä päivä on pyhitetty meidän Herrallemme. Ja älkää olko murheelliset, sillä ilo Herrassa on teidän väkevyytenne.\"",
    "1PE.2.9": "Mutta te olette \"valittu suku, kuninkaallinen papisto, pyhä heimo, omaisuuskansa, julistaaksenne sen jaloja tekoja\", joka on pimeydestä kutsunut teidät ihmeelliseen valkeuteensa;",
    "PSA.18.2": "Herra, minun kallioni, linnani ja pelastajani, minun Jumalani, vuoreni, jonka turviin minä pakenen, minun kilpeni, autuuteni sarvi ja varustukseni.",
    "1CO.15.58": "Sentähden, rakkaat veljeni, olkaa lujat, järkähtämättömät, aina innokkaat Herran työssä, tietäen, että teidän vaivannäkönne ei ole turha Herrassa.",
    "EXO.14.14": "Herra sotii teidän puolestanne, ja te olkaa hiljaa.\"",
    "2CH.15.7": "Mutta te olkaa lujat älkääkä antako kättenne vaipua, sillä teidän työllänne on palkkansa.\"",
    "PHP.4.11-12": "Ei niin, että minä puutteen vuoksi tätä sanon; sillä minä olen oppinut oloihini tyytymään. Osaan elää niukkuudessa, osaan myös elää runsaudessa; kaikkeen ja kaikenlaisiin oloihin minä olen tottunut; sekä olemaan ravittuna että näkemään nälkää, elämään sekä runsaudessa että puutteessa.",
    "ISA.58.11": "Ja Herra johdattaa sinua alati ja ravitsee sinun sielusi kuivissa erämaissa; hän vahvistaa sinun luusi, ja sinä olet oleva niinkuin runsaasti kasteltu puutarha, niinkuin lähde, josta vesi ei koskaan puutu.",
    "MAT.16.24": "Silloin Jeesus sanoi opetuslapsillensa: \"Jos joku tahtoo minun perässäni kulkea, hän kieltäköön itsensä ja ottakoon ristinsä ja seuratkoon minua.",
    "DEU.31.6": "Olkaa lujat ja rohkeat, älkää peljätkö älkääkä säikähtykö heitä, sillä Herra, sinun Jumalasi, käy itse sinun kanssasi; hän ei jätä eikä hylkää sinua.\"",
    "1CO.13.4-5": "Rakkaus on pitkämielinen, rakkaus on lempeä; rakkaus ei kadehdi, ei kerskaa, ei pöyhkeile, ei käyttäydy sopimattomasti, ei etsi omaansa, ei katkeroidu, ei muistele kärsimäänsä pahaa,",
    "ACT.16.31": "Niin he sanoivat: \"Usko Herraan Jeesukseen, niin sinä pelastut, niin myös sinun perhekuntasi\".",
    "1PE.4.10": "Palvelkaa toisianne, kukin sillä armolahjalla, minkä on saanut, Jumalan moninaisen armon hyvinä huoneenhaltijoina.",
    "PSA.46.1": "Jumala on meidän turvamme ja väkevyytemme, apumme hädässä aivan vahva.",
    "ISA.41.13": "Sillä minä, Herra, sinun Jumalasi, tartun sinun oikeaan käteesi, minä sanon sinulle: \"Älä pelkää, minä autan sinua\".",
    "1CO.15.3-4": "Sillä minä annoin teille ennen kaikkea tiedoksi sen, minkä itse olin saanut: että Kristus on kuollut meidän syntiemme tähden, kirjoitusten mukaan, ja että hänet haudattiin ja että hän nousi kuolleista kolmantena päivänä, kirjoitusten mukaan,",
    "JER.17.7-8": "Siunattu on se mies, joka turvaa Herraan, jonka turvana Herra on. Hän on kuin veden partaalle istutettu puu, joka ojentaa juurensa puron puoleen; helteen tuloa se ei peljästy, vaan sen lehvä on vihanta, ei poutavuonnakaan sillä ole huolta, eikä se herkeä hedelmää tekemästä.",
    "PHP.1.6": "varmasti luottaen siihen, että hän, joka on alkanut teissä hyvän työn, on sen täyttävä Kristuksen Jeesuksen päivään saakka.",
    "2CO.12.9": "Ja hän sanoi minulle: \"Minun armossani on sinulle kyllin; sillä minun voimani tulee täydelliseksi heikkoudessa\". Sentähden minä mieluimmin kerskaan heikkoudestani, että Kristuksen voima asettuisi minuun asumaan.",
    "HEB.4.15-16": "Sillä ei meillä ole sellainen ylimmäinen pappi, joka ei voi sääliä meidän heikkouksiamme, vaan joka on ollut kaikessa kiusattu samalla lailla kuin mekin, kuitenkin ilman syntiä. Käykäämme sentähden uskalluksella armon istuimen eteen, että saisimme laupeuden ja löytäisimme armon, avuksemme oikeaan aikaan.",
    "PRO.4.23": "Yli kaiken varottavan varjele sydämesi, sillä sieltä elämä lähtee.",
    "ROM.11.33": "Oi sitä Jumalan rikkauden ja viisauden ja tiedon syvyyttä! Kuinka tutkimattomat ovat hänen tuomionsa ja käsittämättömät hänen tiensä!",
    "JHN.1.1-3": "Alussa oli Sana, ja Sana oli Jumalan tykönä, ja Sana oli Jumala. Hän oli alussa Jumalan tykönä. Kaikki on saanut syntynsä hänen kauttaan, ja ilman häntä ei ole syntynyt mitään, mikä syntynyt on.",
    "PSA.56.3-4": "Mutta sinä päivänä, jota minä pelkään, minä turvaan sinuun. Jumalaan minä luotan ja ylistän hänen sanaansa, Jumalaan minä turvaan enkä pelkää. Mitä liha minulle tekisi?",
    "JHN.10.11": "Minä olen se hyvä paimen. Hyvä paimen antaa henkensä lammasten edestä.",
    "ROM.12.21": "Älä anna pahan itseäsi voittaa, vaan voita sinä paha hyvällä.",
    "MRK.9.23": "Niin Jeesus sanoi hänelle: \"'Jos voit!' Kaikki on mahdollista sille, joka uskoo\".",
    "DEU.33.27": "Sinun turvasi on ikiaikojen Jumala, sinua kannattavat iankaikkiset käsivarret. Hän karkoitti viholliset sinun tieltäsi, hän sanoi: 'Hävitä!'",
    "PRO.17.17": "Ystävä rakastaa ainiaan ja veli syntyy varaksi hädässä.",
    "PSA.19.1": "Taivaat julistavat Jumalan kunniaa, taivaanvahvuus ilmoittaa hänen kättensä tekoja.",
    "MAL.3.10": "Tuokaa täydet kymmenykset varastohuoneeseen, että minun huoneessani olisi ravintoa, ja siten koetelkaa minua, sanoo Herra Sebaot: totisesti minä avaan teille taivaan akkunat ja vuodatan teille siunausta ylenpalttisesti.",
    "JOS.24.15": "Mutta jos pidätte pahana palvella Herraa, niin valitkaa tänä päivänä, ketä tahdotte palvella, niitäkö jumalia, joita teidän isänne palvelivat tuolla puolella virran, vai amorilaisten jumalia, niiden, joiden maassa te asutte. Mutta minä ja minun perheeni palvelemme Herraa.\"",
    "ECC.12.13": "Loppusana kaikesta, mitä on kuultu, on tämä: Pelkää Jumalaa ja pidä hänen käskynsä, sillä niin tulee jokaisen ihmisen tehdä.",
    "PSA.37.23-24": "Herra vahvistaa sen miehen askeleet, jonka tie hänelle kelpaa. Jos hän lankeaa, ei hän maahan sorru, sillä Herra tukee hänen kättänsä.",
    "REV.21.5": "Ja valtaistuimella istuva sanoi: \"Katso, uudeksi minä teen kaikki\". Ja hän sanoi: \"Kirjoita, sillä nämä sanat ovat vakaat ja todet\".",
    "ISA.40.31": "mutta ne, jotka Herraa odottavat, saavat uuden voiman, he kohottavat siipensä kuin kotkat. He juoksevat eivätkä näänny, he vaeltavat eivätkä väsy.",
    "JHN.4.13-14": "Jeesus vastasi ja sanoi hänelle: \"Jokainen, joka juo tätä vettä, janoaa jälleen, mutta joka juo sitä vettä, jota minä hänelle annan, se ei ikinä janoa; vaan se vesi, jonka minä hänelle annan, tulee hänessä sen veden lähteeksi, joka kumpuaa iankaikkiseen elämään\".",
    "HEB.12.1-2": "Sentähden, kun meillä on näin suuri pilvi todistajia ympärillämme, pankaamme mekin pois kaikki, mikä meitä painaa, ja synti, joka niin helposti meidät kietoo, ja juoskaamme kestävinä edessämme olevassa kilvoituksessa, silmät luotuina uskon alkajaan ja täyttäjään, Jeesukseen, joka hänelle tarjona olevan ilon sijasta kärsi ristin, häpeästä välittämättä, ja istui Jumalan valtaistuimen oikealle puolelle.",
    "1JN.4.18": "Pelkoa ei rakkaudessa ole, vaan täydellinen rakkaus karkoittaa pelon, sillä pelossa on rangaistusta; ja joka pelkää, se ei ole päässyt täydelliseksi rakkaudessa.",
    "PSA.118.24": "Tämä on se päivä, jonka Herra on tehnyt; riemuitkaamme ja iloitkaamme siitä.",
    "HEB.12.11": "Mikään kuritus ei tosin sillä kertaa näytä olevan iloksi, vaan murheeksi, mutta jälkeenpäin se antaa vanhurskauden rauhanhedelmän niille, jotka sen kautta ovat harjoitetut.",
    "ECC.4.9-10": "Kahden on parempi kuin yksin, sillä heillä on vaivannäöstänsä hyvä palkka. Jos he lankeavat, niin toinen nostaa ylös toverinsa; mutta voi yksinäistä, jos hän lankeaa! Ei ole toista nostamassa häntä ylös.",
    "2CO.1.3-4": "Kiitetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, laupeuden Isä ja kaiken lohdutuksen Jumala, joka lohduttaa meitä kaikessa ahdistuksessamme, että me sillä lohdutuksella, jolla Jumala meitä itseämme lohduttaa, voisimme lohduttaa niitä, jotka kaikkinaisessa ahdistuksessa ovat.",
    "PSA.30.5": "Sillä silmänräpäyksen kestää hänen vihansa, eliniän hänen armonsa; ehtoolla on itku vieraana, mutta aamulla ilo.",
    "GAL.6.2": "Kantakaa toistenne kuormia, ja niin te täytätte Kristuksen lain.",
    "JHN.14.27": "Rauhan minä jätän teille: minun rauhani-sen minä annan teille. En minä anna teille, niinkuin maailma antaa. Älköön teidän sydämenne olko murheellinen älköönkä peljätkö.",
    "GAL.3.26-28": "Sillä te olette kaikki uskon kautta Jumalan lapsia Kristuksessa Jeesuksessa. Sillä kaikki te, jotka olette Kristukseen kastetut, olette Kristuksen päällenne pukeneet. Ei ole tässä juutalaista eikä kreikkalaista, ei ole orjaa eikä vapaata, ei ole miestä eikä naista; sillä kaikki te olette yhtä Kristuksessa Jeesuksessa.",
    "EXO.33.14": "Hän sanoi: \"Pitäisikö minun kasvojeni käymän sinun kanssasi ja minun viemän sinut lepoon?\"",
    "LUK.1.37": "sillä Jumalalle ei mikään ole mahdotonta.\"",
    "PRO.16.3": "Heitä työsi Herran haltuun, niin sinun hankkeesi menestyvät.",
    "ACT.17.27-28": "että he etsisivät Jumalaa, jos ehkä voisivat hapuilemalla hänet löytää-hänet, joka kuitenkaan ei ole kaukana yhdestäkään meistä; sillä hänessä me elämme ja liikumme ja olemme, niinkuin myös muutamat teidän runoilijoistanne ovat sanoneet: 'Sillä me olemme myös hänen sukuansa'.",
    "JHN.5.24": "Totisesti, totisesti minä sanon teille: joka kuulee minun sanani ja uskoo häneen, joka on minut lähettänyt, sillä on iankaikkinen elämä, eikä hän joudu tuomittavaksi, vaan on siirtynyt kuolemasta elämään.",
    "MRK.1.15": "ja sanoi: \"Aika on täyttynyt, ja Jumalan valtakunta on tullut lähelle; tehkää parannus ja uskokaa evankeliumi\".",
    "PRO.16.9": "Ihmisen sydän aivoittelee hänen tiensä, mutta Herra ohjaa hänen askeleensa.",
    "PSA.46.10": "\"Heretkää ja tietäkää, että minä olen Jumala, korkea kansojen keskellä, korkea maan päällä.\"",
    "2TH.3.16": "Mutta itse rauhan Herra antakoon teille rauhan, aina ja kaikella tavalla. Herra olkoon kaikkien teidän kanssanne.",
    "1TH.5.16-18": "Olkaa aina iloiset. Rukoilkaa lakkaamatta. Kiittäkää joka tilassa. Sillä se on Jumalan tahto teihin nähden Kristuksessa Jeesuksessa.",
    "PHP.3.13-14": "Veljet, minä en vielä katso sitä voittaneeni; mutta yhden minä teen: unhottaen sen, mikä on takana, ja kurottautuen sitä kohti, mikä on edessäpäin, minä riennän kohti päämäärää, voittopalkintoa, johon Jumala on minut taivaallisella kutsumisella kutsunut Kristuksessa Jeesuksessa.",
    "MAT.24.35": "Taivas ja maa katoavat, mutta minun sanani eivät koskaan katoa.",
    "EPH.5.1-2": "Olkaa siis Jumalan seuraajia, niinkuin rakkaat lapset, ja vaeltakaa rakkaudessa, niinkuin Kristuskin rakasti teitä ja antoi itsensä meidän edestämme lahjaksi ja uhriksi, Jumalalle \"suloiseksi tuoksuksi\".",
    "PRO.18.10": "Herran nimi on vahva torni; hurskas juoksee sinne ja saa turvan.",
    "JHN.15.4-5": "Pysykää minussa, niin minä pysyn teissä. Niinkuin oksa ei voi kantaa hedelmää itsestään, ellei se pysy viinipuussa, niin ette tekään, ellette pysy minussa. Minä olen viinipuu, te olette oksat. Joka pysyy minussa ja jossa minä pysyn, se kantaa paljon hedelmää; sillä ilman minua te ette voi mitään tehdä.",
    "PSA.37.4": "silloin sinulla on ilo Herrassa, ja hän antaa sinulle, mitä sinun sydämesi halajaa.",
    "1JN.4.9-10": "Siinä ilmestyi meille Jumalan rakkaus, että Jumala lähetti ainokaisen Poikansa maailmaan, että me eläisimme hänen kauttansa. Siinä on rakkaus-ei siinä, että me rakastimme Jumalaa, vaan siinä, että hän rakasti meitä ja lähetti Poikansa meidän syntiemme sovitukseksi.",
    "JHN.17.3": "Mutta tämä on iankaikkinen elämä, että he tuntevat sinut, joka yksin olet totinen Jumala, ja hänet, jonka sinä olet lähettänyt, Jeesuksen Kristuksen.",
    "2CO.4.6": "Sillä Jumala, joka sanoi: \"Loistakoon valkeus pimeydestä\", on se, joka loisti sydämiimme, että Jumalan kirkkauden tunteminen, sen kirkkauden, joka loistaa Kristuksen kasvoissa, levittäisi valoansa.",
    "COL.3.12-13": "Pukeutukaa siis te, jotka olette Jumalan valituita, pyhiä ja rakkaita, sydämelliseen armahtavaisuuteen, ystävällisyyteen, nöyryyteen, sävyisyyteen, pitkämielisyyteen, kärsikää toinen toistanne ja antakaa toisillenne anteeksi, jos kenellä on moitetta toista vastaan. Niinkuin Herrakin on antanut teille anteeksi, niin myös te antakaa.",
    "PSA.1.1-2": "Autuas se mies, joka ei vaella jumalattomain neuvossa eikä astu syntisten teitä eikä istu, kussa pilkkaajat istuvat, vaan rakastaa Herran lakia ja tutkistelee hänen lakiansa päivät ja yöt!",
    "PRO.3.11-12": "Poikani, älä pidä Herran kuritusta halpana äläkä kyllästy hänen rangaistukseensa; sillä jota Herra rakastaa, sitä hän rankaisee, niinkuin isä poikaa, joka hänelle rakas on.",
    "ECC.3.11": "Kaiken hän on tehnyt kauniisti aikanansa, myös iankaikkisuuden hän on pannut heidän sydämeensä; mutta niin on, ettei ihminen käsitä tekoja, jotka Jumala on tehnyt, ei alkua eikä loppua.",
    "JOL.2.13": "Reväiskää rikki sydämenne, älkää vaatteitanne, ja kääntykää Herran, teidän Jumalanne, tykö; sillä hän on armahtavainen ja laupias, pitkämielinen ja armosta rikas, ja hän katuu pahaa.",
    "GAL.6.9-10": "Ja kun hyvää teemme, älkäämme lannistuko, sillä me saamme ajan tullen niittää, jos emme väsy. Sentähden, kun meillä vielä aikaa on, tehkäämme hyvää kaikille, mutta varsinkin uskonveljille.",
    "PSA.136.1": "Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.",
    "PHP.4.13": "Kaikki minä voin hänessä, joka minua vahvistaa.",
    "EPH.4.32": "Olkaa sen sijaan toisianne kohtaan ystävällisiä, hyväsydämisiä, anteeksiantavaisia toinen toisellenne, niinkuin Jumalakin on Kristuksessa teille anteeksi antanut.",
    "JAS.1.12": "Autuas se mies, joka kiusauksen kestää, sillä kun hänet on koeteltu, on hän saava elämän kruunun, jonka Herra on luvannut niille, jotka häntä rakastavat!",
    "JHN.1.12": "Mutta kaikille, jotka ottivat hänet vastaan, hän antoi voiman tulla Jumalan lapsiksi, niille, jotka uskovat hänen nimeensä,",
    "EPH.3.17-19": "ja Kristuksen asua uskon kautta teidän sydämissänne, niin että te, rakkauteen juurtuneina ja perustuneina, voisitte kaikkien pyhien kanssa käsittää, mikä leveys ja pituus ja korkeus ja syvyys on, ja oppia tuntemaan Kristuksen rakkauden, joka on kaikkea tietoa ylempänä; että tulisitte täyteen Jumalan kaikkea täyteyttä.",
    "PHP.2.9-11": "Sentähden onkin Jumala hänet korkealle korottanut ja antanut hänelle nimen, kaikkia muita nimiä korkeamman, niin että kaikkien polvien pitää Jeesuksen nimeen notkistuman, sekä niitten, jotka taivaissa ovat, että niitten, jotka maan päällä ovat, ja niitten, jotka maan alla ovat, ja jokaisen kielen pitää tunnustaman Isän Jumalan kunniaksi, että Jeesus Kristus on Herra.",
    "PRO.31.30": "Pettävä on sulous, kauneus katoavainen; ylistetty se vaimo, joka Herraa pelkää!",
    "MAT.28.19-20": "Menkää siis ja tehkää kaikki kansat minun opetuslapsikseni, kastamalla heitä Isän ja Pojan ja Pyhän Hengen nimeen ja opettamalla heitä pitämään kaikki, mitä minä olen käskenyt teidän pitää. Ja katso, minä olen teidän kanssanne joka päivä maailman loppuun asti.\"",
    "1JN.3.16": "Siitä me olemme oppineet tuntemaan rakkauden, että hän antoi henkensä meidän edestämme; meidänkin tulee antaa henkemme veljiemme edestä.",
    "EPH.4.1-3": "Niin kehoitan siis minä, joka olen vankina Herrassa, teitä vaeltamaan, niinkuin saamanne kutsumuksen arvo vaatii, kaikessa nöyryydessä ja hiljaisuudessa ja pitkämielisyydessä kärsien toinen toistanne rakkaudessa ja pyrkien säilyttämään hengen yhteyden rauhan yhdyssiteellä:",
    "PSA.100.4-5": "Käykää hänen portteihinsa kiittäen, hänen esikartanoihinsa ylistystä veisaten. Ylistäkää häntä, kiittäkää hänen nimeänsä. Sillä Herra on hyvä; hänen armonsa pysyy iankaikkisesti ja hänen uskollisuutensa polvesta polveen.",
    "HAB.3.17-18": "Sillä ei viikunapuu kukoista, eikä viiniköynnöksissä ole rypäleitä; öljypuun sato pettää, eivätkä pellot tuota syötävää. Lampaat ovat kadonneet tarhasta, eikä ole karjaa vajoissa. Mutta minä riemuitsen Herrassa, iloitsen autuuteni Jumalassa.",
    "ROM.6.23": "Sillä synnin palkka on kuolema, mutta Jumalan armolahja on iankaikkinen elämä Kristuksessa Jeesuksessa, meidän Herrassamme.",
    "LAM.3.22-23": "Herran armoa on, ettemme ole aivan hävinneet, sillä hänen laupeutensa ei ole loppunut: se on joka aamu uusi, ja suuri on hänen uskollisuutensa.",
    "1JN.3.1": "Katsokaa, minkäkaltaisen rakkauden Isä on meille antanut, että meitä kutsutaan Jumalan lapsiksi, joita me olemmekin. Sentähden ei maailma tunne meitä, sillä se ei tunne häntä.",
    "PSA.150.6": "Kaikki, joissa henki on, ylistäkää Herraa! Halleluja!",
    "2CO.4.16-18": "Sentähden me emme lannistu; vaan vaikka ulkonainen ihmisemme menehtyykin, niin sisällinen kuitenkin päivä päivältä uudistuu. Sillä tämä hetkisen kestävä ja kevyt ahdistuksemme tuottaa meille iankaikkisen ja määrättömän kirkkauden, ylenpalttisesti, meille, jotka emme katso näkyväisiä, vaan näkymättömiä; sillä näkyväiset ovat ajallisia, mutta näkymättömät iankaikkisia.",
    "JER.29.12-13": "Silloin te huudatte minua avuksenne, tulette ja rukoilette minua, ja minä kuulen teitä. Te etsitte minua ja löydätte minut, kun te etsitte minua kaikesta sydämestänne.",
    "REV.21.4": "ja hän on pyyhkivä pois kaikki kyyneleet heidän silmistänsä, eikä kuolemaa ole enää oleva, eikä murhetta eikä parkua eikä kipua ole enää oleva, sillä kaikki entinen on mennyt.\"",
    "PSA.84.11": "Sillä Herra Jumala on aurinko ja kilpi; Herra antaa armon ja kunnian, ei hän kiellä hyvää niiltä, jotka nuhteettomasti vaeltavat.",
    "1TI.6.12": "Kilvoittele hyvä uskon kilvoitus, tartu kiinni iankaikkiseen elämään, johon olet kutsuttu ja johon hyvällä tunnustuksella olet tunnustautunut monen todistajan edessä.",
    "LAM.3.25-26": "Hyvä on Herra häntä odottaville, sille sielulle, joka häntä etsii. Hyvä on hiljaisuudessa toivoa Herran apua.",
    "2CO.3.17": "Sillä Herra on Henki, ja missä Herran Henki on, siinä on vapaus.",
    "PSA.91.1-2": "Joka Korkeimman suojassa istuu ja Kaikkivaltiaan varjossa yöpyy, se sanoo: \"Herra on minun turvani ja linnani, hän on minun Jumalani, johon minä turvaan\".",
    "EPH.1.3": "Ylistetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, joka on siunannut meitä taivaallisissa kaikella hengellisellä siunauksella Kristuksessa,",
    "MAT.4.4": "Mutta hän vastasi ja sanoi: \"Kirjoitettu on: 'Ei ihminen elä ainoastaan leivästä, vaan jokaisesta sanasta, joka Jumalan suusta lähtee'.\"",
    "ISA.49.15-16": "Unhottaako vaimo rintalapsensa, niin ettei hän armahda kohtunsa poikaa? Ja vaikka he unhottaisivatkin, minä en sinua unhota. Katso, kätteni hipiään olen minä sinut piirtänyt, sinun muurisi ovat aina minun edessäni.",
    "HEB.10.24-25": "ja valvokaamme toinen toistamme rohkaisuksi toisillemme rakkauteen ja hyviin tekoihin; Älkäämme jättäkö omaa seurakunnankokoustamme, niinkuin muutamien on tapana, vaan kehoittakaamme toisiamme, sitä enemmän, kuta enemmän näette tuon päivän lähestyvän.",
    "ROM.1.16": "Sillä minä en häpeä evankeliumia; sillä se on Jumalan voima, itsekullekin uskovalle pelastukseksi, juutalaiselle ensin, sitten myös kreikkalaiselle.",
    "2TI.1.7": "Sillä Jumala ei ole antanut meille pelkuruuden henkeä, vaan voiman ja rakkauden ja raittiuden hengen.",
    "ISA.40.28-29": "Etkö tiedä, etkö ole kuullut: Herra on iankaikkinen Jumala, joka on luonut maan ääret? Ei hän väsy eikä näänny, hänen ymmärryksensä on tutkimaton. Hän antaa väsyneelle väkeä ja voimattomalle voimaa yltäkyllin.",
    "JHN.8.31-32": "Niin Jeesus sanoi niille juutalaisille, jotka uskoivat häneen: \"Jos te pysytte minun sanassani, niin te totisesti olette minun opetuslapsiani; ja te tulette tuntemaan totuuden, ja totuus on tekevä teidät vapaiksi\".",
    "HEB.11.1": "Mutta usko on luja luottamus siihen, mitä toivotaan, ojentautuminen sen mukaan, mikä ei näy.",
    "ISA.40.11": "Niinkuin paimen hän kaitsee laumaansa, kokoaa karitsat käsivarrellensa ja kantaa niitä sylissään, johdattelee imettäviä lampaita.",
    "JHN.13.34-35": "Uuden käskyn minä annan teille, että rakastatte toisianne, niinkuin minä olen teitä rakastanut-että tekin niin rakastatte toisianne. Siitä kaikki tuntevat teidät minun opetuslapsikseni, jos teillä on keskinäinen rakkaus.\"",
    "JER.1.5": "\"Jo ennenkuin minä valmistin sinut äidin kohdussa, minä sinut tunsin, ja ennenkuin sinä äidistä synnyit, minä sinut pyhitin; minä asetin sinut kansojen profeetaksi\".",
    "EPH.4.29": "Mikään rietas puhe älköön suustanne lähtekö, vaan ainoastaan sellainen, mikä on rakentavaista ja tarpeellista ja on mieluista niille, jotka kuulevat.",
    "JHN.10.10": "Varas ei tule muuta kuin varastamaan ja tappamaan ja tuhoamaan. Minä olen tullut, että heillä olisi elämä ja olisi yltäkylläisyys.",
    "HEB.11.6": "Mutta ilman uskoa on mahdoton olla otollinen; sillä sen, joka Jumalan tykö tulee, täytyy uskoa, että Jumala on ja että hän palkitsee ne, jotka häntä etsivät.",
    "ISA.55.6-7": "Etsikää Herraa silloin, kun hänet löytää voidaan; huutakaa häntä avuksi, kun hän läsnä on. Jumalaton hyljätköön tiensä ja väärintekijä ajatuksensa ja palatkoon Herran tykö, niin hän armahtaa häntä, ja meidän Jumalamme tykö, sillä hänellä on paljon anteeksiantamusta.",
    "JHN.15.16": "Te ette valinneet minua, vaan minä valitsin teidät ja asetin teidät, että te menisitte ja kantaisitte hedelmää ja että teidän hedelmänne pysyisi: että mitä ikinä te anotte Isältä minun nimessäni, hän sen teille antaisi.",
    "1CO.13.13": "Niin pysyvät nyt usko, toivo, rakkaus, nämä kolme; mutta suurin niistä on rakkaus.",
    "ROM.8.38-39": "Sillä minä olen varma siitä, ettei kuolema eikä elämä, ei enkelit eikä henkivallat, ei nykyiset eikä tulevaiset, ei voimat, ei korkeus eikä syvyys, eikä mikään muu luotu voi meitä erottaa Jumalan rakkaudesta, joka on Kristuksessa Jeesuksessa, meidän Herrassamme.",
    "MAT.6.26": "Katsokaa taivaan lintuja: eivät ne kylvä eivätkä leikkaa eivätkä kokoa aittoihin, ja teidän taivaallinen Isänne ruokkii ne. Ettekö te ole paljoa suurempiarvoiset kuin ne?",
    "1TI.1.15": "Varma on se sana ja kaikin puolin vastaanottamisen arvoinen, että Kristus Jeesus on tullut maailmaan syntisiä pelastamaan, joista minä olen suurin.",
    "JAS.1.22": "Mutta olkaa sanan tekijöitä, eikä vain sen kuulijoita, pettäen itsenne.",
    "PSA.145.18": "Herra on lähellä kaikkia, jotka häntä avuksensa huutavat, kaikkia, jotka totuudessa häntä avuksensa huutavat.",
    "MAT.22.37-39": "Niin Jeesus sanoi hänelle: \"'Rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta mielestäsi'. Tämä on suurin ja ensimmäinen käsky. Toinen, tämän vertainen, on: 'Rakasta lähimmäistäsi niinkuin itseäsi'.",
    "PSA.16.11": "Sinä neuvot minulle elämän tien; ylenpalttisesti on iloa sinun kasvojesi edessä, ihanuutta sinun oikeassa kädessäsi iankaikkisesti.",
    "GEN.1.1": "Alussa loi Jumala taivaan ja maan.",
    "JAS.1.5": "Mutta jos joltakin teistä puuttuu viisautta, anokoon sitä Jumalalta, joka antaa kaikille alttiisti ja soimaamatta, niin se hänelle annetaan.",
    "MAT.18.20": "Sillä missä kaksi tahi kolme on kokoontunut minun nimeeni, siinä minä olen heidän keskellänsä.\"",
    "PSA.121.1-2": "Minä nostan silmäni vuoria kohti: mistä tulee minulle apu? Apu minulle tulee Herralta, joka on tehnyt taivaan ja maan.",
    "GAL.5.22-23": "Mutta Hengen hedelmä on rakkaus, ilo, rauha, pitkämielisyys, ystävällisyys, hyvyys, uskollisuus, sävyisyys, itsensähillitseminen. Sellaista vastaan ei ole laki.",
    "ISA.64.8": "Mutta olethan sinä, Herra, meidän isämme; me olemme savi, ja sinä olet meidän valajamme, kaikki me olemme sinun kättesi tekoa.",
    "ROM.10.13": "Sillä \"jokainen, joka huutaa avuksi Herran nimeä, pelastuu\".",
    "COL.3.17": "Ja kaikki, minkä teette sanalla tai työllä, kaikki tehkää Herran Jeesuksen nimessä, kiittäen Isää Jumalaa hänen kauttansa.",
    "MAT.7.7-8": "Anokaa, niin teille annetaan; etsikää, niin te löydätte; kolkuttakaa, niin teille avataan. Sillä jokainen anova saa, ja etsivä löytää, ja kolkuttavalle avataan.",
    "JHN.20.29": "Jeesus sanoi hänelle: \"Sentähden, että minut näit, sinä uskot. Autuaat ne, jotka eivät näe ja kuitenkin uskovat!\"",
    "JER.33.3": "Huuda minua avuksesi, niin minä vastaan sinulle ja ilmoitan sinulle suuria ja salattuja asioita, joita sinä et tiedä.",
    "EZK.36.26": "Ja minä annan teille uuden sydämen, ja uuden hengen minä annan teidän sisimpäänne. Minä poistan teidän ruumiistanne kivisydämen ja annan teille lihasydämen.",
    "ROM.5.8": "Mutta Jumala osoittaa rakkautensa meitä kohtaan siinä, että Kristus, kun me vielä olimme syntisiä, kuoli meidän edestämme.",
    "PSA.119.105": "Sinun sanasi on minun jalkaini lamppu ja valkeus minun tielläni.",
    "ROM.12.1-2": "Niin minä Jumalan armahtavan laupeuden kautta kehoitan teitä, veljet, antamaan ruumiinne eläväksi, pyhäksi, Jumalalle otolliseksi uhriksi; tämä on teidän järjellinen jumalanpalveluksenne. Älkääkä mukautuko tämän maailmanajan mukaan, vaan muuttukaa mielenne uudistuksen kautta, tutkiaksenne, mikä on Jumalan tahto, mikä hyvää ja otollista ja täydellistä.",
    "PSA.119.11": "Minä kätken sinun sanasi sydämeeni, etten tekisi syntiä sinua vastaan.",
    "1CO.16.13-14": "Valvokaa, pysykää lujina uskossa, olkaa miehuulliset, olkaa väkevät. Kaikki, mitä teette, tapahtukoon rakkaudessa.",
    "MAT.11.28-30": "Tulkaa minun tyköni, kaikki työtätekeväiset ja raskautetut, niin minä annan teille levon. Ottakaa minun ikeeni päällenne ja oppikaa minusta, sillä minä olen hiljainen ja nöyrä sydämeltä; niin te löydätte levon sielullenne. Sillä minun ikeeni on sovelias, ja minun kuormani on keveä.\"",
    "1SA.16.7": "Mutta Herra sanoi Samuelille: \"Älä katso hänen näköänsä äläkä kookasta vartaloansa, sillä minä olen hänet hyljännyt. Sillä ei ole, niinkuin ihminen näkee: ihminen näkee ulkomuodon, mutta Herra näkee sydämen.\"",
    "LUK.1.46-47": "Ja Maria sanoi: \"Minun sieluni suuresti ylistää Herraa, ja minun henkeni riemuitsee Jumalasta, vapahtajastani;",
    "GEN.1.27": "Ja Jumala loi ihmisen omaksi kuvaksensa, Jumalan kuvaksi hän hänet loi; mieheksi ja naiseksi hän loi heidät.",
    "GAL.2.20": "ja minä elän, en enää minä, vaan Kristus elää minussa; ja minkä nyt elän lihassa, sen minä elän Jumalan Pojan uskossa, hänen, joka on rakastanut minua ja antanut itsensä minun edestäni.",
    "1CO.2.9": "vaan, niinkuin kirjoitettu on: \"mitä silmä ei ole nähnyt eikä korva kuullut, mikä ei ole ihmisen sydämeen noussut ja minkä Jumala on valmistanut niille, jotka häntä rakastavat\".",
    "COL.3.16": "Runsaasti asukoon teissä Kristuksen sana; opettakaa ja neuvokaa toinen toistanne kaikessa viisaudessa, psalmeilla, kiitosvirsillä ja hengellisillä lauluilla, veisaten kiitollisesti Jumalalle sydämissänne.",
    "NUM.6.24-26": "Herra siunatkoon sinua ja varjelkoon sinua; Herra valistakoon kasvonsa sinulle ja olkoon sinulle armollinen; Herra kääntäköön kasvonsa sinun puoleesi ja antakoon sinulle rauhan.",
    "LUK.11.28": "Mutta hän sanoi: \"Niin, autuaat ovat ne, jotka kuulevat Jumalan sanan ja sitä noudattavat\".",
    "PSA.63.1": "Jumala, sinä olet minun Jumalani, sinua minä etsin varhain; sinua minun sieluni janoaa, sinua halajaa minun ruumiini kuivassa ja nääntyvässä, vedettömässä maassa.",
    "JHN.8.36": "Jos siis Poika tekee teidät vapaiksi, niin te tulette todellisesti vapaiksi.",
    "PRO.15.1": "Leppeä vastaus taltuttaa kiukun, mutta loukkaava sana nostaa vihan.",
    "ISA.43.18-19": "Älkää entisiä muistelko, älkää menneistä välittäkö. Katso, minä teen uutta; nyt se puhkeaa taimelle, ettekö sitä huomaa? Niin, minä teen tien korpeen, virrat erämaahan.",
    "JAS.1.19-20": "Te tiedätte sen, rakkaat veljeni. Mutta olkoon jokainen ihminen nopea kuulemaan, hidas puhumaan, hidas vihaan; sillä miehen viha ei tee sitä, mikä on oikein Jumalan edessä.",
    "EPH.2.10": "Sillä me olemme hänen tekonsa, luodut Kristuksessa Jeesuksessa hyviä töitä varten, jotka Jumala on edeltäpäin valmistanut, että me niissä vaeltaisimme.",
    "ROM.10.17": "Usko tulee siis kuulemisesta, mutta kuuleminen Kristuksen sanan kautta.",
    "JAS.1.2-4": "Veljeni, pitäkää pelkkänä ilona, kun joudutte moninaisiin kiusauksiin, tietäen, että teidän uskonne kestäväisyys koetuksissa saa aikaan kärsivällisyyttä. Ja kärsivällisyys tuottakoon täydellisen teon, että te olisitte täydelliset ja eheät ettekä missään puuttuvaiset.",
    "1TH.5.11": "Sentähden kehoittakaa toisianne ja rakentakaa toinen toistanne, niinkuin teettekin.",
    "1PE.1.3": "Ylistetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, joka suuren laupeutensa mukaan on uudestisynnyttänyt meidät elävään toivoon Jeesuksen Kristuksen kuolleistanousemisen kautta,",
    "JHN.1.5": "Ja valkeus loistaa pimeydessä, ja pimeys ei sitä käsittänyt.",
    "LEV.19.18": "Älä kosta äläkä pidä vihaa kansasi lapsia vastaan, vaan rakasta lähimmäistäsi niinkuin itseäsi. Minä olen Herra.",
    "MAT.5.8": "Autuaita ovat puhdassydämiset, sillä he saavat nähdä Jumalan.",
    "ISA.61.1": "Herran, Herran Henki on minun päälläni, sillä hän on voidellut minut julistamaan ilosanomaa nöyrille, lähettänyt minut sitomaan särjettyjä sydämiä, julistamaan vangituille vapautusta ja kahlituille kirvoitusta,",
    "RUT.1.16": "Mutta Ruut vastasi: \"Älä vaadi minua jättämään sinua ja kääntymään takaisin, pois sinun tyköäsi. Sillä mihin sinä menet, sinne minäkin menen, ja mihin sinä jäät, sinne minäkin jään; sinun kansasi on minun kansani, sinun Jumalasi on minun Jumalani.",
    "JHN.8.12": "Niin Jeesus taas puhui heille sanoen: \"Minä olen maailman valkeus; joka minua seuraa, se ei pimeydessä vaella, vaan hänellä on oleva elämän valkeus\".",
    "2TH.3.3": "Mutta Herra on uskollinen, ja hän on vahvistava teitä ja varjeleva teidät pahasta.",
    "PSA.34.4": "Minä etsin Herraa, ja hän vastasi minulle, hän vapahti minut kaikista peljätyksistäni.",
    "TIT.3.5": "pelasti hän meidät, ei vanhurskaudessa tekemiemme tekojen ansiosta, vaan laupeutensa mukaan uudestisyntymisen peson ja Pyhän Hengen uudistuksen kautta,",
    "LUK.12.32": "Älä pelkää, sinä piskuinen lauma; sillä teidän Isänne on nähnyt hyväksi antaa teille valtakunnan.",
    "PSA.23.6": "Sula hyvyys ja laupeus seuraavat minua kaiken elinaikani; ja minä saan asua Herran huoneessa päivieni loppuun asti.",
    "MIC.7.18-19": "Kuka on Jumala, niinkuin sinä olet, joka annat pahat teot anteeksi ja käyt ohitse perintösi jäännöksen rikosten? Ei hän pidä vihaa iäti, sillä hänellä on halu laupeuteen. Hän armahtaa meitä jälleen, polkee maahan meidän pahat tekomme. Kaikki heidän syntinsä sinä heität meren syvyyteen.",
    "2CO.4.7": "Mutta tämä aarre on meillä saviastioissa, että tuo suunnattoman suuri voima olisi Jumalan eikä näyttäisi tulevan meistä.",
    "GEN.50.20": "Te tosin hankitsitte minua vastaan pahaa, mutta Jumala on kääntänyt sen hyväksi, että hän saisi aikaan sen, mikä nyt on tapahtunut, ja pitäisi hengissä paljon kansaa.",
    "PSA.32.8": "\"Minä opetan sinua ja osoitan sinulle tien, jota sinun tulee vaeltaa; minä neuvon sinua, minun silmäni sinua vartioitsee\".",
    "MAT.6.19-21": "Älkää kootko itsellenne aarteita maan päälle, missä koi ja ruoste raiskaa ja missä varkaat murtautuvat sisään ja varastavat. Vaan kootkaa itsellenne aarteita taivaaseen, missä ei koi eikä ruoste raiskaa ja missä eivät varkaat murtaudu sisään eivätkä varasta. Sillä missä sinun aarteesi on, siellä on myös sinun sydämesi.",
    "ROM.15.13": "Mutta toivon Jumala täyttäköön teidät kaikella ilolla ja rauhalla uskossa, niin että teillä olisi runsas toivo Pyhän Hengen voiman kautta.",
    "JHN.3.30": "Hänen tulee kasvaa, mutta minun vähetä.",
    "DEU.7.9": "Ja tiedä siis, että Herra, sinun Jumalasi, on Jumala, uskollinen Jumala, joka pitää liiton ja on laupias tuhansiin polviin asti niille, jotka häntä rakastavat ja pitävät hänen käskynsä,",
    "HEB.13.8": "Jeesus Kristus on sama eilen ja tänään ja iankaikkisesti.",
    "EPH.2.4-5": "mutta Jumala, joka on laupeudesta rikas, suuren rakkautensa tähden, jolla hän on meitä rakastanut, on tehnyt meidät, jotka olimme kuolleet rikoksiimme, eläviksi Kristuksen kanssa-armosta te olette pelastetut-",
    "PRO.10.12": "Viha virittää riitoja, mutta rakkaus peittää rikkomukset kaikki.",
    "3JN.1.4": "Minulla ei ole suurempaa iloa kuin se, että kuulen lasteni vaeltavan totuudessa.",
    "ECC.3.1": "Kaikella on määräaika, ja aikansa on joka asialla taivaan alla.",
    "PSA.4.8": "Rauhassa minä käyn levolle ja nukun, sillä sinä, Herra, yksin annat minun turvassa asua.",
    "1CO.15.55-57": "\"Kuolema, missä on sinun voittosi? Kuolema, missä on sinun otasi?\" Mutta kuoleman ota on synti, ja synnin voima on laki. Mutta kiitos olkoon Jumalan, joka antaa meille voiton meidän Herramme Jeesuksen Kristuksen kautta!",
    "JER.29.11": "Sillä minä tunnen ajatukseni, jotka minulla on teitä kohtaan, sanoo Herra: rauhan eikä turmion ajatukset; minä annan teille tulevaisuuden ja toivon.",
    "PRO.11.25": "Hyväätekeväinen sielu tulee ravituksi, ja joka muita virvoittaa, se itse kostuu.",
    "2PE.3.18": "ja kasvakaa meidän Herramme ja Vapahtajamme Jeesuksen Kristuksen armossa ja tuntemisessa. Hänen olkoon kunnia sekä nyt että hamaan iankaikkisuuden päivään.",
    "2TI.2.15": "Pyri osoittautumaan Jumalalle semmoiseksi, joka koetukset kestää, työntekijäksi, joka ei työtään häpeä, joka oikein jakelee totuuden sanaa.",
    "PSA.107.1": "Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.",
    "2CO.9.8": "Ja Jumala on voimallinen antamaan teille ylenpalttisesti kaikkea armoa, että teillä kaikessa aina olisi kaikkea riittävästi, voidaksenne ylenpalttisesti tehdä kaikkinaista hyvää;",
    "JHN.10.27-28": "Minun lampaani kuulevat minun ääntäni, ja minä tunnen ne, ja ne seuraavat minua. Ja minä annan heille iankaikkisen elämän, ja he eivät ikinä huku, eikä kukaan ryöstä heitä minun kädestäni.",
    "1CO.10.13": "Teitä ei ole kohdannut muu kuin inhimillinen kiusaus; ja Jumala on uskollinen, hän ei salli teitä kiusattavan yli voimienne, vaan salliessaan kiusauksen hän valmistaa myös pääsyn siitä, niin että voitte sen kestää.",
    "MRK.11.24": "Sentähden minä sanon teille: kaikki, mitä te rukoilette ja anotte, uskokaa saaneenne, niin se on teille tuleva.",
    "GAL.5.13-14": "Te olette näet kutsutut vapauteen, veljet; älkää vain salliko vapauden olla yllykkeeksi lihalle, vaan palvelkaa toisianne rakkaudessa. Sillä kaikki laki on täytetty yhdessä käskysanassa, tässä: \"Rakasta lähimmäistäsi niinkuin itseäsi\".",
    "ACT.4.12": "Eikä ole pelastusta yhdessäkään toisessa; sillä ei ole taivaan alla muuta nimeä ihmisille annettu, jossa meidän pitäisi pelastuman.\"",
    "ISA.41.10": "Älä pelkää, sillä minä olen sinun kanssasi; älä arkana pälyile, sillä minä olen sinun Jumalasi; minä vahvistan sinua, minä autan sinua, minä tuen sinua vanhurskauteni oikealla kädellä.",
    "1JN.4.16": "Ja me olemme oppineet tuntemaan ja me uskomme sen rakkauden, mikä Jumalalla on meihin. Jumala on rakkaus, ja joka pysyy rakkaudessa, se pysyy Jumalassa, ja Jumala pysyy hänessä.",
    "EXO.15.2": "Herra on minun väkevyyteni ja ylistysvirteni, ja hänestä tuli minulle pelastus. Hän on minun Jumalani, ja minä ylistän häntä, hän on minun isäni Jumala, ja minä kunnioitan häntä.",
    "REV.22.13": "Minä olen A ja O, ensimmäinen ja viimeinen, alku ja loppu.",
    "2TI.4.7-8": "Minä olen hyvän kilvoituksen kilvoitellut, juoksun päättänyt, uskon säilyttänyt. Tästedes on minulle talletettuna vanhurskauden seppele, jonka Herra, vanhurskas tuomari, on antava minulle sinä päivänä, eikä ainoastaan minulle, vaan myös kaikille, jotka hänen ilmestymistään rakastavat.",
    "PSA.121.7-8": "Herra varjelee sinut kaikesta pahasta, hän varjelee sinun sielusi. Herra varjelee sinun lähtemisesi ja tulemisesi, nyt ja iankaikkisesti.",
    "ISA.53.5": "mutta hän on haavoitettu meidän rikkomustemme tähden, runneltu meidän pahain tekojemme tähden. Rangaistus oli hänen päällänsä, että meillä rauha olisi, ja hänen haavainsa kautta me olemme paratut.",
    "ROM.10.9-10": "Sillä jos sinä tunnustat suullasi Jeesuksen Herraksi ja uskot sydämessäsi, että Jumala on hänet kuolleista herättänyt, niin sinä pelastut; sillä sydämen uskolla tullaan vanhurskaaksi ja suun tunnustuksella pelastutaan.",
    "1PE.2.24": "joka \"itse kantoi meidän syntimme\" ruumiissansa ristinpuuhun, että me, synneistä pois kuolleina, eläisimme vanhurskaudelle; ja hänen \"haavainsa kautta te olette paratut\".",
    "2PE.1.3": "Koska hänen jumalallinen voimansa on lahjoittanut meille kaiken, mikä elämään ja jumalisuuteen tarvitaan, hänen tuntemisensa kautta, joka on kutsunut meidät kirkkaudellaan ja täydellisyydellään,",
    "PSA.94.19": "Kun minulla on sydämessäni paljon murheita, niin sinun lohdutuksesi ilahuttaa minun sieluni.",
    "MAT.6.34": "Älkää siis murehtiko huomisesta päivästä, sillä huominen päivä pitää murheen itsestään. Riittää kullekin päivälle oma vaivansa.\"",
    "PHP.4.4": "Iloitkaa aina Herrassa! Vieläkin minä sanon: iloitkaa!",
    "EPH.2.8-9": "Sillä armosta te olette pelastetut uskon kautta, ette itsenne kautta-se on Jumalan lahja- ette tekojen kautta, ettei kukaan kerskaisi.",
    "1PE.5.10": "Mutta kaiken armon Jumala, joka on kutsunut teidät iankaikkiseen kirkkauteensa Kristuksessa, vähän aikaa kärsittyänne, hän on teidät valmistava, teitä tukeva, vahvistava ja lujittava.",
    "ACT.1.8": "vaan, kun Pyhä Henki tulee teihin, niin te saatte voiman, ja te tulette olemaan minun todistajani sekä Jerusalemissa että koko Juudeassa ja Samariassa ja aina maan ääriin saakka\".",
    "JHN.3.16": "Sillä niin on Jumala maailmaa rakastanut, että hän antoi ainokaisen Poikansa, ettei yksikään, joka häneen uskoo, hukkuisi, vaan hänellä olisi iankaikkinen elämä.",
    "1CH.16.11": "Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojansa.",
    "1TI.4.12": "Älköön kukaan nuoruuttasi katsoko ylen, vaan ole sinä uskovaisten esikuva puheessa, vaelluksessa, rakkaudessa, uskossa, puhtaudessa.",
    "EPH.6.10-11": "Lopuksi, vahvistukaa Herrassa ja hänen väkevyytensä voimassa. Pukekaa yllenne Jumalan koko sota-asu, voidaksenne kestää perkeleen kavalat juonet.",
    "JHN.15.12-13": "Tämä on minun käskyni, että te rakastatte toisianne, niinkuin minä olen teitä rakastanut. Sen suurempaa rakkautta ei ole kenelläkään, kuin että hän antaa henkensä ystäväinsä edestä.",
    "ZEC.4.6": "Ja hän lausui ja sanoi minulle näin: \"Tämä on Herran sana Serubbaabelille, näin kuuluva: Ei sotaväellä eikä voimalla, vaan minun Hengelläni, sanoo Herra Sebaot.",
    "ROM.8.37": "Mutta näissä kaikissa me saamme jalon voiton hänen kauttansa, joka meitä on rakastanut.",
    "PRO.1.7": "Herran pelko on tiedon alku; hullut pitävät halpana viisauden ja kurin.",
    "PSA.27.14": "Odota Herraa. Ole luja, ja vahva olkoon sinun sydämesi. Odota Herraa.",
    "MRK.16.15": "Ja hän sanoi heille: \"Menkää kaikkeen maailmaan ja saarnatkaa evankeliumia kaikille luoduille.",
    "JHN.16.33": "Tämän minä olen teille puhunut, että teillä olisi minussa rauha. Maailmassa teillä on ahdistus; mutta olkaa turvallisella mielellä: minä olen voittanut maailman.\"",
    "1PE.4.8": "Ennen kaikkea olkoon teidän rakkautenne toisianne kohtaan harras, sillä \"rakkaus peittää syntien paljouden\".",
    "PRO.3.5-6": "Turvaa Herraan kaikesta sydämestäsi äläkä nojaudu omaan ymmärrykseesi. Tunne hänet kaikilla teilläsi, niin hän sinun polkusi tasoittaa.",
    "ROM.8.31-32": "Mitä me siis tähän sanomme? Jos Jumala on meidän puolellamme, kuka voi olla meitä vastaan? Hän, joka ei säästänyt omaa Poikaansakaan, vaan antoi hänet alttiiksi kaikkien meidän edestämme, kuinka hän ei lahjoittaisi meille kaikkea muutakin hänen kanssansa?",
    "HAB.3.19": "Herra, Herra on minun voimani. Hän tekee minun jalkani nopsiksi niinkuin peurat ja antaa minun käydä kukkuloillani. Veisuunjohtajalle; minun kielisoittimillani.",
    "MIC.6.8": "Hän on ilmoittanut sinulle, ihminen, mikä hyvä on; ja mitä muuta Herra sinulta vaatii, kuin että teet sitä, mikä oikein on, rakastat laupeutta ja vaellat nöyrästi Jumalasi edessä?",
    "MAT.17.20": "Niin hän sanoi heille: \"Teidän epäuskonne tähden; sillä totisesti minä sanon teille: jos teillä olisi uskoa sinapinsiemenenkään verran, niin te voisitte sanoa tälle vuorelle: 'Siirry täältä tuonne', ja se siirtyisi, eikä mikään olisi teille mahdotonta\".",
    "MRK.10.45": "Sillä ei Ihmisen Poikakaan tullut palveltavaksi, vaan palvelemaan ja antamaan henkensä lunnaiksi monen edestä.\"",
    "DAN.12.3": "Ja taidolliset loistavat, niinkuin taivaanvahvuus loistaa, ja ne, jotka monta vanhurskauteen saattavat, niinkuin tähdet, aina ja iankaikkisesti.",
    "PHP.4.6-7": "Älkää mistään murehtiko, vaan kaikessa saattakaa pyyntönne rukouksella ja anomisella kiitoksen kanssa Jumalalle tiettäväksi, ja Jumalan rauha, joka on kaikkea ymmärrystä ylempi, on varjeleva teidän sydämenne ja ajatuksenne Kristuksessa Jeesuksessa.",
    "2CO.4.8-9": "Me olemme kaikin tavoin ahdingossa, mutta emme umpikujassa, neuvottomat, mutta emme toivottomat, vainotut, mutta emme hyljätyt, maahan kukistetut, mutta emme tuhotut.",
    "PRO.16.24": "Lempeät sanat ovat mesileipää; ne ovat makeat sielulle ja lääkitys luille.",
    "1JN.1.5": "Ja tämä on se sanoma, jonka olemme häneltä kuulleet ja jonka me teille julistamme: että Jumala on valkeus ja ettei hänessä ole mitään pimeyttä.",
    "DEU.6.4-5": "Kuule, Israel! Herra, meidän Jumalamme, Herra on yksi. Ja rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta voimastasi.",
    "PSA.23.4": "Vaikka minä vaeltaisin pimeässä laaksossa, en minä pelkäisi mitään pahaa, sillä sinä olet minun kanssani; sinun vitsasi ja sauvasi minua lohduttavat.",
    "ROM.8.18": "Sillä minä päätän, että tämän nykyisen ajan kärsimykset eivät ole verrattavat siihen kirkkauteen, joka on ilmestyvä meihin.",
    "REV.3.20": "Katso, minä seison ovella ja kolkutan; jos joku kuulee minun ääneni ja avaa oven, niin minä käyn hänen tykönsä sisälle ja aterioitsen hänen kanssaan, ja hän minun kanssani.",
    "ISA.30.15": "Sillä näin sanoo Herra, Herra, Israelin Pyhä: Kääntymällä ja pysymällä hiljaa te pelastutte, rauhallisuus ja luottamus on teidän väkevyytenne; mutta te ette tahtoneet,",
    "JHN.6.35": "Jeesus sanoi heille: \"Minä olen elämän leipä; joka tulee minun tyköni, se ei koskaan isoa, ja joka uskoo minuun, se ei koskaan janoa.",
    "ACT.20.35": "Kaikessa minä olen osoittanut teille, että näin työtä tehden tulee huolehtia heikoista ja muistaa nämä Herran Jeesuksen sanat, jotka hän itse sanoi: 'Autuaampi on antaa kuin ottaa'.\"",
    "JAS.5.16": "Tunnustakaa siis toisillenne syntinne ja rukoilkaa toistenne puolesta, että te parantuisitte; vanhurskaan rukous voi paljon, kun se on harras.",
    "ISA.1.18": "Niin tulkaa, käykäämme oikeutta keskenämme, sanoo Herra. Vaikka teidän syntinne ovat veriruskeat, tulevat ne lumivalkeiksi; vaikka ne ovat purppuranpunaiset, tulevat ne villanvalkoisiksi.",
    "PRO.27.17": "Rauta rautaa hioo, ja ihminen toistansa hioo.",
    "JHN.1.14": "Ja Sana tuli lihaksi ja asui meidän keskellämme, ja me katselimme hänen kirkkauttansa, senkaltaista kirkkautta, kuin ainokaisella Pojalla on Isältä; ja hän oli täynnä armoa ja totuutta.",
    "1JN.1.9": "Jos me tunnustamme syntimme, on hän uskollinen ja vanhurskas, niin että hän antaa meille synnit anteeksi ja puhdistaa meidät kaikesta vääryydestä.",
    "MAT.6.33": "Vaan etsikää ensin Jumalan valtakuntaa ja hänen vanhurskauttansa, niin myös kaikki tämä teille annetaan.",
    "1CO.13.12": "Sillä nyt me näemme kuin kuvastimessa, arvoituksen tavoin, mutta silloin kasvoista kasvoihin; nyt minä tunnen vajavaisesti, mutta silloin minä olen tunteva täydellisesti, niinkuin minut itsenikin täydellisesti tunnetaan.",
    "REV.1.8": "\"Minä olen A ja O\", sanoo Herra Jumala, joka on ja joka oli ja joka tuleva on, Kaikkivaltias.",
    "PSA.28.7": "Herra on minun voimani ja kilpeni; häneen minun sydämeni turvasi, ja minä sain avun. Siitä minun sydämeni riemuitsee, ja veisuullani minä häntä ylistän.",
    "DEU.31.8": "Ja Herra itse käy sinun edelläsi, hän on sinun kanssasi, hän ei jätä sinua eikä hylkää sinua; älä pelkää äläkä arkaile.\"",
    "HEB.4.12": "Sillä Jumalan sana on elävä ja voimallinen ja terävämpi kuin mikään kaksiteräinen miekka ja tunkee lävitse, kunnes se erottaa sielun ja hengen, nivelet sekä ytimet, ja on sydämen ajatusten ja aivoitusten tuomitsija;",
    "MAT.19.14": "Niin Jeesus sanoi: \"Antakaa lasten olla, älkääkä estäkö heitä tulemasta minun tyköni, sillä senkaltaisten on taivasten valtakunta\".",
    "JAS.4.7-8": "Olkaa siis Jumalalle alamaiset; mutta vastustakaa perkelettä, niin se teistä pakenee. Lähestykää Jumalaa, niin hän lähestyy teitä. Puhdistakaa kätenne, te syntiset, ja tehkää sydämenne puhtaiksi, te kaksimieliset.",
    "PSA.139.13-14": "Sillä sinä olet luonut minun munaskuuni, sinä kudoit minut kokoon äitini kohdussa. Minä kiitän sinua siitä, että olen tehty ylen ihmeellisesti; ihmeelliset ovat sinun tekosi, sen minun sieluni kyllä tietää.",
    "HOS.6.3": "Niin tuntekaamme, pyrkikäämme tuntemaan Herra: hänen nousunsa on varma kuin aamurusko, hän tulee meille kuin sade, kuin kevätsade, joka kostuttaa maan.",
    "1CO.10.31": "Söittepä siis tai joitte tai teittepä mitä hyvänsä, tehkää kaikki Jumalan kunniaksi.",
    "JOS.1.8": "Älköön tämä lain kirja sinun suustasi poistuko, vaan tutkiskele sitä päivät ja yöt, että tarkoin noudattaisit kaikkea, mitä siihen on kirjoitettu, sillä silloin sinä onnistut teilläsi ja silloin sinä menestyt.",
    "2CH.7.14": "mutta minun kansani, joka on otettu minun nimiini, nöyrtyy, ja he rukoilevat ja etsivät minun kasvojani ja palajavat pahoilta teiltänsä, niin minä kuulen taivaasta ja annan anteeksi heidän syntinsä ja teen heidän maansa jälleen terveeksi.",
    "PSA.19.14": "Kelvatkoot sinulle minun suuni sanat ja minun sydämeni ajatukset sinun edessäsi, Herra, minun kallioni ja lunastajani.",
    "JHN.14.1-3": "\"Älköön teidän sydämenne olko murheellinen. Uskokaa Jumalaan, ja uskokaa minuun. Minun Isäni kodissa on monta asuinsijaa. Jos ei niin olisi, sanoisinko minä teille, että minä menen valmistamaan teille sijaa? Ja vaikka minä menen valmistamaan teille sijaa, tulen minä takaisin ja otan teidät tyköni, että tekin olisitte siellä, missä minä olen.",
    "PSA.147.3": "Hän parantaa ne, joilla on särjetty sydän, ja sitoo heidän haavansa.",
    "PHP.4.19": "Mutta minun Jumalani on rikkautensa mukaisesti täyttävä kaikki teidän tarpeenne kirkkaudessa, Kristuksessa Jeesuksessa.",
    "2CO.13.14": "Herran Jeesuksen Kristuksen armo ja Jumalan rakkaus ja Pyhän Hengen osallisuus olkoon kaikkien teidän kanssanne.",
    "1PE.3.15": "vaan pyhittäkää Herra Kristus sydämissänne ja olkaa aina valmiit vastaamaan jokaiselle, joka teiltä kysyy sen toivon perustusta, joka teissä on, kuitenkin sävyisyydellä ja pelolla,",
    "MAT.25.40": "Niin Kuningas vastaa ja sanoo heille: 'Totisesti minä sanon teille: kaikki, mitä olette tehneet yhdelle näistä minun vähimmistä veljistäni, sen te olette tehneet minulle'.",
    "PSA.139.23-24": "Tutki minua, Jumala, ja tunne minun sydämeni, koettele minua ja tunne minun ajatukseni. Ja katso: jos minun tieni on vaivaan vievä, niin johdata minut iankaikkiselle tielle.",
    "JOS.1.9": "Olenhan minä sinua käskenyt: Ole luja ja rohkea; älä säikähdy äläkä arkaile, sillä Herra, sinun Jumalasi, on sinun kanssasi, missä ikinä kuljetkin.\"",
    "JAS.3.17-18": "Mutta ylhäältä tuleva viisaus on ensiksikin puhdas, sitten rauhaisa, lempeä, taipuisa, täynnä laupeutta ja hyviä hedelmiä, se ei epäile, ei teeskentele. Vanhurskauden hedelmä kylvetään rauhassa rauhan tekijöille.",
    "REV.22.17": "Ja Henki ja morsian sanovat: \"Tule!\" Ja joka kuulee, sanokoon: \"Tule!\" Ja joka janoaa, tulkoon, ja joka tahtoo, ottakoon elämän vettä lahjaksi.",
    "MAT.19.26": "Niin Jeesus katsoi heihin ja sanoi heille: \"Ihmisille se on mahdotonta, mutta Jumalalle on kaikki mahdollista\".",
    "PSA.103.11-12": "Sillä niin korkealla kuin taivas on maasta, niin voimallinen on hänen armonsa niitä kohtaan, jotka häntä pelkäävät. Niin kaukana kuin itä on lännestä, niin kauas hän siirtää meistä rikkomuksemme.",
    "REV.4.11": "\"Sinä, meidän Herramme ja meidän Jumalamme, olet arvollinen saamaan ylistyksen ja kunnian ja voiman, sillä sinä olet luonut kaikki, ja sinun tahdostasi ne ovat olemassa ja ovat luodut\".",
    "PHP.1.21": "Sillä elämä on minulle Kristus, ja kuolema on voitto.",
    "2TI.3.16-17": "Jokainen kirjoitus, joka on syntynyt Jumalan Hengen vaikutuksesta, on myös hyödyllinen opetukseksi, nuhteeksi, ojennukseksi, kasvatukseksi vanhurskaudessa, että Jumalan ihminen olisi täydellinen, kaikkiin hyviin tekoihin valmistunut.",
    "JER.31.3": "Kaukaa ilmestyy minulle Herra: \"Iankaikkisella rakkaudella minä olen sinua rakastanut, sentähden minä olen vetänyt sinua puoleeni armosta.",
    "LUK.15.7": "Minä sanon teille: samoin on ilo taivaassa suurempi yhdestä syntisestä, joka tekee parannuksen, kuin yhdeksästäkymmenestä yhdeksästä vanhurskaasta, jotka eivät parannusta tarvitse.",
    "ISA.54.10": "Sillä vuoret väistykööt ja kukkulat horjukoot, mutta minun armoni ei sinusta väisty, eikä minun rauhanliittoni horju, sanoo Herra, sinun armahtajasi.",
    "EPH.3.20-21": "Mutta hänelle, joka voi tehdä enemmän, monin verroin enemmän kuin kaikki, mitä me anomme tai ymmärrämme, sen voiman mukaan, joka meissä vaikuttaa, hänelle kunnia seurakunnassa ja Kristuksessa Jeesuksessa kautta kaikkien sukupolvien, aina ja iankaikkisesti! Amen.",
    "ROM.5.3-5": "Eikä ainoastaan se, vaan meidän kerskauksenamme ovat myös ahdistukset, sillä me tiedämme, että ahdistus saa aikaan kärsivällisyyttä, mutta kärsivällisyys koettelemuksen kestämistä, ja koettelemuksen kestäminen toivoa; mutta toivo ei saata häpeään; sillä Jumalan rakkaus on vuodatettu meidän sydämiimme Pyhän Hengen kautta, joka on meille annettu.",
    "1JN.4.19": "Me rakastamme, sillä hän on ensin rakastanut meitä.",
    "JHN.14.6": "Jeesus sanoi hänelle: \"Minä olen tie ja totuus ja elämä; ei kukaan tule Isän tykö muutoin kuin minun kauttani.",
    "1PE.5.6-7": "Nöyrtykää siis Jumalan väkevän käden alle, että hän ajallansa teidät korottaisi, ja \"heittäkää kaikki murheenne hänen päällensä, sillä hän pitää teistä huolen\".",
    "EST.4.14": "Jos sinä tänä aikana olet vaiti, tulee apu ja pelastus juutalaisille muualta, mutta sinä ja sinun isäsi perhe tuhoudutte. Kuka tietää, etkö sinä juuri tällaista aikaa varten ole päässyt kuninkaalliseen arvoon?\"",
    "PSA.51.10": "Jumala, luo minuun puhdas sydän ja anna minulle uusi, vahva henki.",
    "LUK.6.37-38": "Älkääkä tuomiko, niin ei teitäkään tuomita; älkää kadotustuomiota lausuko, niin ei teillekään kadotustuomiota lausuta. Antakaa anteeksi, niin teillekin anteeksi annetaan. Antakaa, niin teille annetaan. Hyvä mitta, sullottu, pudistettu ja kukkurainen, annetaan teidän helmaanne; sillä millä mitalla te mittaatte, sillä mitataan teille takaisin.\"",
    "PRO.2.6": "Sillä Herra antaa viisautta, hänen suustansa lähtee tieto ja taito.",
    "MAT.7.24-25": "Sentähden on jokainen, joka kuulee nämä minun sanani ja tekee niiden mukaan, verrattava ymmärtäväiseen mieheen, joka huoneensa kalliolle rakensi. Ja rankkasade lankesi, ja virrat tulvivat, ja tuulet puhalsivat ja syöksyivät sitä huonetta vastaan, mutta se ei sortunut, sillä se oli kalliolle perustettu.",
    "TIT.2.11-13": "Sillä Jumalan armo on ilmestynyt pelastukseksi kaikille ihmisille ja kasvattaa meitä, että me, hyljäten jumalattomuuden ja maailmalliset himot, eläisimme siveästi ja vanhurskaasti ja jumalisesti nykyisessä maailmanajassa, odottaessamme autuaallisen toivon täyttymistä ja suuren Jumalan ja Vapahtajamme Kristuksen Jeesuksen kirkkauden ilmestymistä,",
    "LUK.2.14": "\"Kunnia Jumalalle korkeuksissa, ja maassa rauha ihmisten kesken, joita kohtaan hänellä on hyvä tahto!\"",
    "JOB.23.10": "Sillä hän tietää, kussa minä kuljen. Jos hän tutkisi minut, kullan kaltaisena minä selviäisin.",
    "2CO.9.6-7": "Huomatkaa tämä: joka niukasti kylvää, se myös niukasti niittää, ja joka runsaasti kylvää, se myös runsaasti niittää. Antakoon kukin, niinkuin hänen sydämensä vaatii, ei surkeillen eikä pakosta; sillä iloista antajaa Jumala rakastaa.",
    "PRO.19.21": "Monet ovat miehen mielessä aivoitukset, mutta Herran neuvo on pysyväinen.",
    "ROM.5.1-2": "Koska me siis olemme uskosta vanhurskaiksi tulleet, niin meillä on rauha Jumalan kanssa meidän Herramme Jeesuksen Kristuksen kautta, jonka kautta myös olemme uskossa saaneet pääsyn tähän armoon, jossa me nyt olemme, ja meidän kerskauksemme on Jumalan kirkkauden toivo.",
    "LUK.6.27-28": "Mutta teille, jotka kuulette, minä sanon: rakastakaa vihollisianne, tehkää hyvää niille, jotka teitä vihaavat, siunatkaa niitä, jotka teitä kiroavat, rukoilkaa niiden edestä, jotka teitä parjaavat.",
    "PRO.22.6": "Totuta poikanen tiensä suuntaan, niin hän ei vanhanakaan siitä poikkea.",
    "NUM.23.19": "Ei Jumala ole ihminen, niin että hän valhettelisi, eikä ihmislapsi, että hän katuisi. Sanoisiko hän jotakin eikä sitä tekisi, puhuisiko jotakin eikä sitä täyttäisi?",
    "PHP.4.8": "Ja vielä, veljet, kaikki, mikä on totta, mikä kunnioitettavaa, mikä oikeaa, mikä puhdasta, mikä rakastettavaa, mikä hyvältä kuuluvaa, jos on jokin avu ja jos on jotakin kiitettävää, sitä ajatelkaa;",
    "COL.2.6-7": "Niinkuin te siis olette omaksenne ottaneet Kristuksen Jeesuksen, Herran, niin vaeltakaa hänessä, juurtuneina häneen ja hänessä rakentuen ja uskossa vahvistuen, niinkuin teille on opetettu; ja olkoon teidän kiitoksenne ylitsevuotavainen.",
    "ROM.12.12": "Olkaa toivossa iloiset, ahdistuksessa kärsivälliset, rukouksessa kestävät.",
    "PHP.2.3-4": "ettekä tee mitään itsekkyydestä tai turhan kunnian pyynnöstä, vaan että nöyryydessä pidätte toista parempana kuin itseänne ja että katsotte kukin, ette vain omaanne, vaan toistenkin parasta.",
    "1JN.5.14-15": "Ja tämä on se uskallus, joka meillä on häneen, että jos me jotakin anomme hänen tahtonsa mukaan, niin hän kuulee meitä. Ja jos me tiedämme hänen kuulevan meitä, mitä ikinä anommekin, niin tiedämme, että meillä myös on kaikki se, mitä olemme häneltä anoneet.",
    "EPH.5.8": "Ennen te olitte pimeys, mutta nyt te olette valkeus Herrassa. Vaeltakaa valkeuden lapsina",
    "1JN.4.7-8": "Rakkaani, rakastakaamme toinen toistamme, sillä rakkaus on Jumalasta; ja jokainen, joka rakastaa, on Jumalasta syntynyt ja tuntee Jumalan. Joka ei rakasta, se ei tunne Jumalaa, sillä Jumala on rakkaus.",
    "PSA.103.1-2": "Kiitä Herraa, minun sieluni, ja kaikki, mitä minussa on, hänen pyhää nimeänsä. Kiitä Herraa, minun sieluni, äläkä unhota, mitä hyvää hän on sinulle tehnyt,",
    "HOS.6.6": "Sillä laupeutta minä haluan enkä uhria, ja Jumalan tuntemista enemmän kuin polttouhreja;",
    "ROM.8.1": "Niin ei nyt siis ole mitään kadotustuomiota niille, jotka Kristuksessa Jeesuksessa ovat.",
    "ISA.60.1": "Nouse, ole kirkas, sillä sinun valkeutesi tulee, ja Herran kunnia koittaa sinun ylitsesi.",
    "1TH.5.23-24": "Mutta itse rauhan Jumala pyhittäköön teidät kokonansa, ja säilyköön koko teidän henkenne ja sielunne ja ruumiinne nuhteettomana meidän Herramme Jeesuksen Kristuksen tulemukseen. Hän, joka teitä kutsuu, on uskollinen, ja hän on sen myös tekevä.",
    "1CO.6.19-20": "Vai ettekö tiedä, että teidän ruumiinne on Pyhän Hengen temppeli, joka Henki teissä on ja jonka te olette saaneet Jumalalta, ja ettette ole itsenne omat? Sillä te olette kalliisti ostetut. Kirkastakaa siis Jumala ruumiissanne.",
    "GEN.28.15": "Ja katso, minä olen sinun kanssasi ja varjelen sinua, missä ikinä kuljet, ja saatan sinut takaisin tähän maahan; sillä minä en jätä sinua, ennenkuin olen toteuttanut sen, minkä minä olen sinulle puhunut.\"",
    "PSA.73.26": "Vaikka minun ruumiini ja sieluni nääntyisi, Jumala on minun sydämeni kallio ja minun osani iankaikkisesti.",
    "SNG.8.7": "Eivät suuret vedet voi rakkautta sammuttaa, eivät virrat sitä tulvaansa upottaa. Jos joku tarjoaisi kaikki talonsa tavarat rakkauden hinnaksi, häntä vain halveksuttaisiin.\"",
    "JER.32.17": "\"Oi Herra, Herra! Katso, sinä olet tehnyt taivaan ja maan suurella voimallasi ja ojennetulla käsivarrellasi: ei mikään ole sinulle mahdotonta;",
    "1CH.16.34": "Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.",
    "GAL.5.1": "Vapauteen Kristus vapautti meidät. Pysykää siis lujina, älkääkä antako uudestaan sitoa itseänne orjuuden ikeeseen.",
    "PSA.34.18": "Lähellä on Herra niitä, joilla on särjetty sydän, ja hän pelastaa ne, joilla on murtunut mieli.",
    "DAN.3.17-18": "Jos niin käy, voi meidän Jumalamme kyllä pelastaa meidät tulisesta pätsistä, ja hän pelastaa myös sinun kädestäsi, kuningas. Ja vaikka ei pelastaisikaan, niin tiedä se, kuningas, että me emme palvele sinun jumaliasi emmekä kumartaen rukoile kultaista kuvapatsasta, jonka sinä olet pystyttänyt.\"",
    "1TI.1.17": "Mutta iankaikkiselle kuninkaalle, katoamattomalle, näkymättömälle, ainoalle Jumalalle, kunnia ja kirkkaus aina ja iankaikkisesti! Amen.",
    "PSA.86.5": "Sillä sinä, Herra, olet hyvä ja anteeksiantavainen, suuri armossa kaikille, jotka sinua avuksensa huutavat.",
    "AMO.5.24": "Mutta oikeus virratkoon kuin vesi ja vanhurskaus niinkuin ehtymätön puro.",
    "JAS.1.17": "Jokainen hyvä anti ja jokainen täydellinen lahja tulee ylhäältä, valkeuksien Isältä, jonka tykönä ei ole muutosta, ei vaihteen varjoa.",
    "JUD.1.24-25": "Mutta hänelle, joka voi varjella teidät lankeamasta ja asettaa teidät nuhteettomina, riemuitsevina, kirkkautensa eteen, hänelle, ainoalle Jumalalle ja meidän pelastajallemme Herramme Jeesuksen Kristuksen kautta, hänelle kunnia, majesteetti, voima ja valta ennen kaikkia aikoja ja nyt ja iankaikkisesti! Amen.",
    "2PE.3.9": "Ei Herra viivytä lupauksensa täyttämistä, niinkuin muutamat pitävät sitä viivyttelemisenä, vaan hän on pitkämielinen teitä kohtaan, sillä hän ei tahdo, että kukaan hukkuu, vaan että kaikki tulevat parannukseen.",
    "ISA.9.6": "Sillä lapsi on meille syntynyt, poika on meille annettu, jonka hartioilla on herraus, ja hänen nimensä on: Ihmeellinen neuvonantaja, Väkevä Jumala, Iankaikkinen isä, Rauhanruhtinas.",
    "LUK.2.10-11": "Mutta enkeli sanoi heille: \"Älkää peljätkö; sillä katso, minä ilmoitan teille suuren ilon, joka on tuleva kaikelle kansalle: teille on tänä päivänä syntynyt Vapahtaja, joka on Kristus, Herra, Daavidin kaupungissa.",
    "1TI.6.6-8": "Ja suuri voitto onkin jumalisuus yhdessä tyytyväisyyden kanssa. Sillä me emme ole maailmaan mitään tuoneet, emme myös voi täältä mitään viedä; mutta kun meillä on elatus ja vaatteet, niin tyytykäämme niihin.",
    "NAM.1.7": "Hyvä on Herra, turva ahdistuksen päivänä, ja hän tuntee ne, jotka häneen luottavat.",
    "PSA.27.1": "Herra on minun valkeuteni ja autuuteni: ketä minä pelkään! Herra on minun elämäni turva: ketä minä vapisen!",
    "COL.1.15-17": "ja hän on näkymättömän Jumalan kuva, esikoinen ennen kaikkea luomakuntaa. Sillä hänessä luotiin kaikki, mikä taivaissa ja mikä maan päällä on, näkyväiset ja näkymättömät, olkoot ne valtaistuimia tai herrauksia, hallituksia tai valtoja, kaikki on luotu hänen kauttansa ja häneen, ja hän on ennen kaikkia, ja hänessä pysyy kaikki voimassa.",
    "ZEP.3.17": "Herra, sinun Jumalasi, on sinun keskelläsi, sankari, joka auttaa. Hän ilolla iloitsee sinusta, hän on ääneti, sillä hän rakastaa sinua, hän sinusta riemulla riemuitsee.\"",
    "PSA.90.12": "Opeta meitä laskemaan päivämme oikein, että me saisimme viisaan sydämen.",
    "ROM.8.24-25": "Sillä toivossa me olemme pelastetut, mutta toivo, jonka näkee täyttyneen, ei ole mikään toivo; kuinka kukaan sitä toivoo, minkä näkee? Mutta jos toivomme, mitä emme näe, niin me odotamme sitä kärsivällisyydellä.",
    "PSA.39.7": "Ja nyt, mitä minä odotan, Herra? Sinuun minä panen toivoni.",
    "LAM.3.21-23": "Tämän minä painan sydämeeni, sentähden minä toivon. Herran armoa on, ettemme ole aivan hävinneet, sillä hänen laupeutensa ei ole loppunut: se on joka aamu uusi, ja suuri on hänen uskollisuutensa.",
    "PSA.71.5": "Sillä sinä olet minun toivoni, Herra, Herra, minun turvani hamasta nuoruudestani.",
    "HEB.6.19": "Se toivo meille on ikäänkuin sielun ankkuri, varma ja luja, joka ulottuu esiripun sisäpuolelle asti,",
    "PSA.130.5": "Minä odotan Herraa, minun sieluni odottaa, ja minä panen toivoni hänen sanaansa.",
    "PRO.23.18": "niin sinulla totisesti on tulevaisuus, ja toivosi ei mene turhaan.",
    "PSA.42.11": "Miksi murehdit, minun sieluni, ja miksi olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä saan kiittää häntä, minun kasvojeni apua, minun Jumalaani.",
    "TIT.2.13": "odottaessamme autuaallisen toivon täyttymistä ja suuren Jumalan ja Vapahtajamme Kristuksen Jeesuksen kirkkauden ilmestymistä,",
    "HEB.10.23": "pysykäämme järkähtämättä toivon tunnustuksessa, sillä hän, joka antoi lupauksen, on uskollinen;",
    "PSA.33.22": "Sinun armosi, Herra, olkoon meidän päällämme, niinkuin me panemme toivomme sinuun.",
    "1PE.1.13": "Vyöttäkää sentähden mielenne kupeet ja olkaa raittiit; ja pankaa täysi toivonne siihen armoon, joka teille tarjotaan Jeesuksen Kristuksen ilmestymisessä.",
    "PSA.31.24": "Olkaa lujat, ja olkoon teidän sydämenne rohkea, te kaikki, jotka Herraa odotatte.",
    "COL.1.27": "joille Jumala tahtoi tehdä tiettäväksi, kuinka suuri pakanain keskuudessa on tämän salaisuuden kirkkaus: Kristus teissä, kirkkauden toivo.",
    "PSA.62.5": "Odota yksin Jumalaa hiljaisuudessa, minun sieluni, sillä häneltä tulee minun toivoni.",
    "PSA.147.11": "Herra mielistyy niihin, jotka häntä pelkäävät, jotka panevat toivonsa hänen armoonsa.",
    "1TH.4.13-14": "Mutta me emme tahdo pitää teitä, veljet, tietämättöminä siitä, kuinka poisnukkuneiden on, ettette murehtisi niinkuin muut, joilla ei toivoa ole. Sillä jos uskomme, että Jeesus on kuollut ja noussut ylös, niin samoin on Jumala Jeesuksen kautta myös tuova poisnukkuneet esiin yhdessä hänen kanssaan.",
    "PRO.13.12": "Pitkä odotus tekee sydämen sairaaksi, mutta täyttynyt halu on elämän puu.",
    "PSA.119.114": "Sinä olet minun suojani ja kilpeni, sinun sanaasi minä panen toivoni.",
    "2CO.4.17-18": "Sillä tämä hetkisen kestävä ja kevyt ahdistuksemme tuottaa meille iankaikkisen ja määrättömän kirkkauden, ylenpalttisesti, meille, jotka emme katso näkyväisiä, vaan näkymättömiä; sillä näkyväiset ovat ajallisia, mutta näkymättömät iankaikkisia.",
    "ISA.26.3-4": "Vakaamieliselle sinä talletat rauhan, rauhan, sillä hän turvaa sinuun. Turvatkaa Herraan ainiaan, sillä Herra, Herra on iankaikkinen kallio.",
    "PSA.37.5": "Anna tiesi Herran haltuun ja turvaa häneen, kyllä hän sen tekee.",
    "PSA.9.10": "Ja sinuun turvaavat ne, jotka sinun nimesi tuntevat; sillä sinä et hylkää niitä, jotka sinua etsivät, Herra.",
    "PSA.20.7": "Toiset turvaavat vaunuihin, toiset hevosiin, mutta me tunnustamme Herran, Jumalamme, nimeä.",
    "PSA.62.8": "Turvatkaa häneen joka aika, te kansa; vuodattakaa hänen eteensä sydämenne. Jumala on meidän turvamme. Sela.",
    "PSA.112.7": "Ei hän pelkää pahaa sanomaa, hänen sydämensä on vahva, sillä hän turvaa Herraan.",
    "PSA.118.8": "Parempi on luottaa Herraan, kuin turvata ihmisiin.",
    "ISA.12.2": "Katso, Jumala on minun pelastukseni; minä olen turvassa enkä pelkää, sillä Herra, Herra on minun väkevyyteni ja ylistysvirteni, hän tuli minulle pelastukseksi.\"",
    "PSA.125.1": "Jotka Herraan turvaavat, ovat kuin Siionin vuori: se ei horju, vaan pysyy iankaikkisesti.",
    "PSA.143.8": "Suo minun varhain kuulla sinun armoasi, sillä sinuun minä turvaan. Osoita minulle tie, jota minun tulee käydä, sillä sinun tykösi minä ylennän sieluni.",
    "PRO.29.25": "Ihmispelko panee paulan, mutta Herraan luottavainen on turvattu.",
    "PSA.91.2": "se sanoo: \"Herra on minun turvani ja linnani, hän on minun Jumalani, johon minä turvaan\".",
    "2CO.5.7": "sillä me vaellamme uskossa emmekä näkemisessä.",
    "PSA.40.4": "Autuas se mies, joka panee turvansa Herraan eikä käänny ylpeiden puoleen eikä niitten, jotka valheeseen eksyvät!",
    "PSA.13.5-6": "Mutta minä turvaan sinun armoosi; riemuitkoon minun sydämeni sinun avustasi. Minä veisaan Herralle, sillä hän on tehnyt minulle hyvin.",
    "PSA.84.12": "Herra Sebaot, autuas se ihminen, joka sinuun turvaa!",
    "PRO.16.20": "Joka painaa mieleensä sanan, se löytää onnen; ja autuas se, joka Herraan turvaa!",
    "PSA.32.10": "Jumalattomalla on monta vaivaa, mutta joka Herraan turvaa, häntä ympäröitsee armo.",
    "ISA.50.10": "Kuka teistä pelkää Herraa ja kuulee hänen palvelijansa ääntä? Joka vaeltaa pimeydessä ja valoa vailla, se luottakoon Herran nimeen ja turvautukoon Jumalaansa.",
    "PSA.37.3": "Turvaa Herraan ja tee sitä, mikä hyvä on, asu maassa ja noudata totuutta;",
    "PSA.115.11": "Te, Herraa pelkääväiset, turvatkaa Herraan-hän on heidän apunsa ja kilpensä.",
    "ROM.4.20-21": "mutta Jumalan lupausta hän ei epäuskossa epäillyt, vaan vahvistui uskossa, antaen kunnian Jumalalle, ja oli täysin varma siitä, että minkä Jumala on luvannut, sen hän voi myös täyttää.",
    "1JN.4.18-19": "Pelkoa ei rakkaudessa ole, vaan täydellinen rakkaus karkoittaa pelon, sillä pelossa on rangaistusta; ja joka pelkää, se ei ole päässyt täydelliseksi rakkaudessa. Me rakastamme, sillä hän on ensin rakastanut meitä.",
    "1JN.3.18": "Lapsukaiset, älkäämme rakastako sanalla tai kielellä, vaan teossa ja totuudessa.",
    "COL.3.14": "Mutta kaiken tämän lisäksi pukeutukaa rakkauteen, mikä on täydellisyyden side.",
    "ROM.13.10": "Rakkaus ei tee lähimmäiselle mitään pahaa. Sentähden on rakkaus lain täyttämys.",
    "DEU.6.5": "Ja rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta voimastasi.",
    "1CO.16.14": "Kaikki, mitä teette, tapahtukoon rakkaudessa.",
    "EPH.5.2": "ja vaeltakaa rakkaudessa, niinkuin Kristuskin rakasti teitä ja antoi itsensä meidän edestämme lahjaksi ja uhriksi, Jumalalle \"suloiseksi tuoksuksi\".",
    "GAL.5.13": "Te olette näet kutsutut vapauteen, veljet; älkää vain salliko vapauden olla yllykkeeksi lihalle, vaan palvelkaa toisianne rakkaudessa.",
    "PSA.136.26": "Kiittäkää taivaan Jumalaa, sillä hänen armonsa pysyy iankaikkisesti.",
    "LUK.6.35": "Vaan rakastakaa vihollisianne ja tehkää hyvää ja lainatkaa, toivomatta saavanne mitään takaisin; niin teidän palkkanne on oleva suuri, ja te tulette Korkeimman lapsiksi, sillä hän on hyvä kiittämättömille ja pahoille.",
    "ROM.12.9-10": "Olkoon rakkaus vilpitön, kammokaa pahaa, riippukaa hyvässä kiinni. Olkaa veljellisessä rakkaudessa helläsydämiset toisianne kohtaan; toinen toisenne kunnioittamisessa kilpailkaa keskenänne.",
    "1JN.4.10-11": "Siinä on rakkaus-ei siinä, että me rakastimme Jumalaa, vaan siinä, että hän rakasti meitä ja lähetti Poikansa meidän syntiemme sovitukseksi. Rakkaani, jos Jumala on näin meitä rakastanut, niin mekin olemme velvolliset rakastamaan toinen toistamme.",
    "EPH.4.2": "kaikessa nöyryydessä ja hiljaisuudessa ja pitkämielisyydessä kärsien toinen toistanne rakkaudessa",
    "PSA.86.15": "Mutta sinä, Herra, olet laupias ja armahtavainen Jumala, pitkämielinen, suuri armossa ja totuudessa.",
    "EXO.20.12": "Kunnioita isääsi ja äitiäsi, että kauan eläisit siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.",
    "PSA.127.3-5": "Katso, lapset ovat Herran lahja, ja kohdun hedelmä on anti. Niinkuin nuolet sankarin kädessä, niin ovat nuoruudessa synnytetyt pojat. Onnellinen se mies, jonka viini on niitä täynnä! Eivät he joudu häpeään, kun portissa puhuttelevat vihamiehiänsä.",
    "EPH.6.1-3": "Lapset, olkaa vanhemmillenne kuuliaiset Herrassa, sillä se on oikein. \"Kunnioita isääsi ja äitiäsi\" -tämä on ensimmäinen käsky, jota seuraa lupaus- \"että menestyisit ja kauan eläisit maan päällä\".",
    "COL.3.20-21": "Lapset, olkaa vanhemmillenne kuuliaiset kaikessa, sillä se on otollista Herrassa. Isät, älkää kiihoittako lapsianne, etteivät he kävisi aroiksi.",
    "PRO.17.6": "Vanhusten kruunu ovat lastenlapset, ja isät ovat lasten kunnia.",
    "PSA.103.17": "Mutta Herran armo pysyy iankaikkisesta iankaikkiseen niille, jotka häntä pelkäävät, ja hänen vanhurskautensa lasten lapsille,",
    "DEU.6.6-7": "Nämä sanat, jotka minä tänä päivänä sinulle annan, painukoot sydämeesi. Ja teroita niitä lastesi mieleen ja puhu niistä kotona istuessasi ja tietä käydessäsi, maata pannessasi ja ylös noustessasi.",
    "GEN.2.24": "Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa, ja he tulevat yhdeksi lihaksi.",
    "PRO.31.28-29": "Hänen poikansa nousevat ja kiittävät hänen onneansa; hänen miehensä nousee ja ylistää häntä: \"Paljon on naisia, toimellisia menoissaan, mutta yli niitten kaikkien kohoat sinä\".",
    "EPH.5.25": "Miehet, rakastakaa vaimojanne, niinkuin Kristuskin rakasti seurakuntaa ja antoi itsensä alttiiksi sen edestä,",
    "1TI.5.8": "Mutta jos joku ei pidä huolta omaisistaan ja varsinkaan ei perhekuntalaisistaan, niin hän on kieltänyt uskon ja on uskotonta pahempi.",
    "PSA.128.3": "Niinkuin hedelmällinen viiniköynnös on sinun emäntäsi sinun huoneesi perällä, niinkuin öljypuun vesat ovat sinun lapsesi sinun pöytäsi ympärillä.",
    "PRO.1.8-9": "Kuule, poikani, isäsi kuritusta äläkä hylkää äitisi opetusta, sillä ne ovat ihana seppele sinun päähäsi ja käädyt sinun kaulaasi.",
    "PSA.133.1": "Katso, kuinka hyvää ja suloista on, että veljekset sovussa asuvat!",
    "PRO.20.7": "Vanhurskas vaeltaa nuhteettomasti, onnelliset ovat lapset hänen jälkeensä.",
    "ISA.54.13": "Sinun lapsesi ovat kaikki Herran opetuslapsia, ja suuri rauha on sinun lapsillasi oleva.",
    "MAL.4.6": "Ja hän on kääntävä jälleen isien sydämet lasten puoleen ja lasten sydämet heidän isiensä puoleen, etten minä tulisi ja löisi maata, vihkisi sitä tuhon omaksi.",
    "PRO.15.20": "Viisas poika on isällensä iloksi, mutta tyhmä ihminen halveksii äitiänsä.",
    "EPH.5.33": "Mutta myös teistä kukin kohdaltaan rakastakoon vaimoaan niinkuin itseänsä; mutta vaimo kunnioittakoon miestänsä.",
    "PRO.23.24-25": "neen saa riemuita vanhurskaan isä; joka viisaan on siittänyt, sillä on ilo hänestä. Olkoon sinun isälläsi ja äidilläsi ilo, sinun synnyttäjäsi riemuitkoon.",
    "GEN.18.19": "Sillä minä olen valinnut hänet, että hän käskisi lapsiansa ja perhettänsä, joka jää hänen jälkeensä, noudattamaan Herran tietä ja tekemään sitä, mikä vanhurskaus ja oikeus on, jotta Herra antaisi Aabrahamille tapahtua, mitä hän on hänelle luvannut.\"",
    "PSA.68.6": "Jumala, joka antaa hyljätyille kodin ja johtaa vangitut onneen. Vain niskoittelijat asuvat kuivassa maassa.",
    "PRO.18.22": "Joka vaimon löysi, se onnen löysi, sai Herralta mielisuosion.",
    "COL.3.18-19": "Vaimot, olkaa miehillenne alamaiset, niinkuin sopii Herrassa. Miehet, rakastakaa vaimojanne, älkääkä olko heitä kohtaan katkerat.",
    "PRO.6.20": "Säilytä, poikani, isäsi käsky äläkä hylkää äitisi opetusta.",
    "PRO.31.10": "Kelpo vaimon kuka löytää? Sellaisen arvo on helmiä paljon kalliimpi.",
    "ROM.5.1": "Koska me siis olemme uskosta vanhurskaiksi tulleet, niin meillä on rauha Jumalan kanssa meidän Herramme Jeesuksen Kristuksen kautta,",
    "COL.3.15": "Ja vallitkoon teidän sydämissänne Kristuksen rauha, johon te olette kutsututkin yhdessä ruumiissa, ja olkaa kiitolliset.",
    "PSA.29.11": "Herra antaa kansallensa väkevyyden, Herra siunaa kansaansa rauhalla.",
    "MAT.5.9": "Autuaita ovat rauhantekijät, sillä heidät pitää Jumalan lapsiksi kutsuttaman.",
    "ROM.12.18": "Jos mahdollista on ja mikäli teistä riippuu, eläkää rauhassa kaikkien ihmisten kanssa.",
    "PSA.34.14": "vältä pahaa ja tee hyvää, etsi rauhaa ja pyri siihen.",
    "PRO.16.7": "Jos miehen tiet ovat Herralle otolliset, saattaa hän vihamiehetkin sovintoon hänen kanssansa.",
    "ISA.32.17": "Silloin vanhurskauden hedelmä on rauha, vanhurskauden vaikutus lepo ja turvallisuus iankaikkisesti.",
    "PSA.119.165": "Suuri rauha on niillä, jotka rakastavat sinun lakiasi, eikä heille kompastusta tule.",
    "ROM.14.17": "sillä ei Jumalan valtakunta ole syömistä ja juomista, vaan vanhurskautta ja rauhaa ja iloa Pyhässä Hengessä.",
    "EPH.2.14": "Sillä hän on meidän rauhamme, hän, joka teki molemmat yhdeksi ja purki erottavan väliseinän, nimittäin vihollisuuden,",
    "PSA.85.8": "Minä tahdon kuulla, mitä Jumala, Herra, puhuu: hän puhuu rauhaa kansallensa, hurskaillensa; älkööt he kääntykö jälleen tyhmyyteen.",
    "JAS.3.18": "Vanhurskauden hedelmä kylvetään rauhassa rauhan tekijöille.",
    "HEB.12.14": "Pyrkikää rauhaan kaikkien kanssa ja pyhitykseen, sillä ilman sitä ei kukaan ole näkevä Herraa;",
    "ISA.55.12": "Sillä iloiten te lähdette, ja rauhassa teitä saatetaan; vuoret ja kukkulat puhkeavat riemuun teidän edessänne, ja kaikki kedon puut paukuttavat käsiänsä.",
    "PSA.37.11": "Mutta nöyrät perivät maan ja iloitsevat suuresta rauhasta.",
    "1PE.3.11": "kääntyköön pois pahasta ja tehköön hyvää, etsiköön rauhaa ja pyrkiköön siihen.",
    "ROM.8.6": "Sillä lihan mieli on kuolema, mutta hengen mieli on elämä ja rauha;",
    "PSA.122.6-7": "Toivottakaa rauhaa Jerusalemille, menestykööt ne, jotka sinua rakastavat. Rauha olkoon sinun muuriesi sisällä, olkoon onni sinun linnoissasi.",
    "ISA.48.18": "Jospa ottaisit minun käskyistäni vaarin, niin olisi sinun rauhasi niinkuin virta ja sinun vanhurskautesi niinkuin meren aallot;",
    "ISA.40.29": "Hän antaa väsyneelle väkeä ja voimattomalle voimaa yltäkyllin.",
    "PSA.46.1-2": "Jumala on meidän turvamme ja väkevyytemme, apumme hädässä aivan vahva. Sentähden emme pelkää, vaikka maa järkkyisi ja vuoret meren pohjaan vajoaisivat,",
    "EPH.6.10": "Lopuksi, vahvistukaa Herrassa ja hänen väkevyytensä voimassa.",
    "2CO.12.9-10": "Ja hän sanoi minulle: \"Minun armossani on sinulle kyllin; sillä minun voimani tulee täydelliseksi heikkoudessa\". Sentähden minä mieluimmin kerskaan heikkoudestani, että Kristuksen voima asettuisi minuun asumaan. Sentähden minä olen mielistynyt heikkouteen, pahoinpitelyihin, hätään, vainoihin, ahdistuksiin, Kristuksen tähden; sillä kun olen heikko, silloin minä olen väkevä.",
    "1CO.16.13": "Valvokaa, pysykää lujina uskossa, olkaa miehuulliset, olkaa väkevät.",
    "PSA.118.14": "Herra on minun väkevyyteni ja ylistysvirteni, ja hän tuli minulle pelastajaksi.",
    "PSA.138.3": "Sinä päivänä, jona minä huusin, sinä vastasit minulle; sinä rohkaisit minua: minun sieluni sai voiman.",
    "PSA.105.4": "Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojansa.",
    "PSA.119.28": "Minun sieluni itkee murheesta; vahvista minua sanasi jälkeen.",
    "2SA.22.33": "se Jumala, joka on minun vahva turvani ja johdattaa nuhteetonta hänen tiellänsä,",
    "PSA.59.17": "Sinä, minun väkevyyteni, sinulle minä veisaan kiitosta, sillä Jumala on minun linnani ja minun armollinen Jumalani.",
    "EPH.3.16": "että hän kirkkautensa runsauden mukaisesti antaisi teidän, sisällisen ihmisenne puolesta, voimassa vahvistua hänen Henkensä kautta",
    "ISA.66.13": "Niinkuin äiti lohduttaa lastansa, niin minä lohdutan teitä, ja Jerusalemissa te saatte lohdutuksen.",
    "MAT.5.4": "Autuaita ovat murheelliset, sillä he saavat lohdutuksen.",
    "PSA.119.50": "Se on minun lohdutukseni kurjuudessani, että sinun lupauksesi minua virvoittaa.",
    "ISA.40.1": "\"Lohduttakaa, lohduttakaa minun kansaani\", sanoo teidän Jumalanne.",
    "1PE.5.7": "ja \"heittäkää kaikki murheenne hänen päällensä, sillä hän pitää teistä huolen\".",
    "ISA.49.13": "Riemuitkaa, te taivaat, iloitse, sinä maa, puhjetkaa riemuun, te vuoret, sillä Herra lohduttaa kansaansa ja armahtaa kurjiansa.",
    "PSA.119.76": "Sinun armosi olkoon minun lohdutukseni, niinkuin sinä olet palvelijallesi luvannut.",
    "ISA.51.12": "Minä, minä olen teidän lohduttajanne; mikä olet sinä, että pelkäät ihmistä, joka on kuolevainen, ihmislasta, jonka käy niinkuin ruohon,",
    "PSA.9.9": "Niin Herra on sorretun linna, linna ahdingon aikoina.",
    "JHN.14.18": "En minä jätä teitä orvoiksi; minä tulen teidän tykönne.",
    "PSA.71.21": "Anna minun arvoni kasvaa ja lohduta minua jälleen.",
    "2TH.2.16-17": "Ja meidän Herramme Jeesus Kristus itse ja Jumala, meidän Isämme, joka on rakastanut meitä ja armossa antanut meille iankaikkisen lohdutuksen ja hyvän toivon, lohduttakoon teidän sydämiänne ja vahvistakoon teitä kaikessa hyvässä työssä ja puheessa.",
    "PSA.138.7": "Vaikka minä vaellan ahdistuksen keskellä, niin sinä virvoitat minut. Sinä ojennat kätesi minun vihamiesteni vihaa vastaan, ja sinun oikea kätesi auttaa minua.",
    "ISA.61.1-3": "Herran, Herran Henki on minun päälläni, sillä hän on voidellut minut julistamaan ilosanomaa nöyrille, lähettänyt minut sitomaan särjettyjä sydämiä, julistamaan vangituille vapautusta ja kahlituille kirvoitusta, julistamaan Herran otollista vuotta ja meidän Jumalamme kostonpäivää, lohduttamaan kaikkia murheellisia, panemaan Siionin murheellisten päähän-antamaan heille-juhlapäähineen tuhkan sijaan, iloöljyä murheen sijaan, ylistyksen vaipan masentuneen hengen sijaan; ja heidän nimensä on oleva \"vanhurskauden tammet\", \"Herran istutus\", hänen kirkkautensa ilmoitukseksi.",
    "PRO.3.13-14": "Autuas se ihminen, joka on löytänyt viisauden, ihminen, joka on saanut taidon. Sillä parempi on hankkia sitä kuin hopeata, ja siitä saatu voitto on kultaa jalompi.",
    "PRO.9.10": "Herran pelko on viisauden alku, ja Pyhimmän tunteminen on ymmärrystä. -",
    "PSA.111.10": "Herran pelko on viisauden alku, hyvä ymmärrys kaikille, jotka sitä noudattavat. Hänen ylistyksensä pysyy iankaikkisesti.",
    "PRO.4.7": "Viisauden alku on: hanki viisautta, ja kaikella muulla hankkimallasi hanki ymmärrystä.",
    "ECC.7.12": "Sillä viisauden varjossa on kuin rahan varjossa, mutta tieto on hyödyllisempi: viisaus pitää haltijansa elossa.",
    "PRO.16.16": "Parempi kultaa on hankkia viisautta, kalliimpi hopeata hankkia ymmärrystä.",
    "JAS.3.17": "Mutta ylhäältä tuleva viisaus on ensiksikin puhdas, sitten rauhaisa, lempeä, taipuisa, täynnä laupeutta ja hyviä hedelmiä, se ei epäile, ei teeskentele.",
    "PRO.11.2": "Mihin ylpeys tulee, sinne tulee häpeäkin, mutta nöyräin tykönä on viisaus.",
    "PRO.12.15": "Hullun tie on hänen omissa silmissään oikea, mutta joka neuvoa kuulee, on viisas.",
    "PRO.19.20": "Kuule neuvoa, ota kuritus varteen, että olisit vasta viisaampi.",
    "EPH.5.15-16": "Katsokaa siis tarkoin, kuinka vaellatte: ei niinkuin tyhmät, vaan niinkuin viisaat, ja ottakaa vaari oikeasta hetkestä, sillä aika on paha.",
    "PRO.15.22": "Hankkeet sortuvat, missä neuvonpito puuttuu; mutta ne toteutuvat, missä on runsaasti neuvonantajia.",
    "PRO.13.20": "Vaella viisasten kanssa, niin viisastut; tyhmäin seuratoverin käy pahoin.",
    "1CO.1.25": "Sillä Jumalan hulluus on viisaampi kuin ihmiset, ja Jumalan heikkous on väkevämpi kuin ihmiset.",
    "PRO.18.15": "Tietoa hankkii ymmärtäväisen sydän, tietoa etsii viisasten korva.",
    "PRO.24.3-4": "Viisaudella talo rakennetaan ja ymmärryksellä vahvaksi varustetaan. Taidolla täytetään kammiot, kaikkea kallista ja ihanaa tavaraa täyteen.",
    "COL.2.2-3": "että heidän sydämensä, yhteenliittyneinä rakkaudessa, saisivat kehoitusta omistamaan täyden ymmärtämyksen koko rikkauden ja pääsisivät tuntemaan Jumalan salaisuuden, Kristuksen, jossa kaikki viisauden ja tiedon aarteet ovat kätkettyinä.",
    "PRO.3.7": "Älä ole viisas omissa silmissäsi. Pelkää Herraa ja karta pahaa.",
    "PSA.119.98-100": "Sinun käskysi tekevät minut vihollisiani viisaammaksi, sillä ne ovat minun omani iankaikkisesti. Minä olen kaikkia opettajiani taitavampi, sillä minä tutkistelen sinun todistuksiasi. Minä olen ymmärtäväisempi kuin vanhat, sillä minä otan vaarin sinun asetuksistasi.",
    "PRO.17.27-28": "Joka hillitsee sanansa, on taitava, ja mielensä malttava on ymmärtäväinen mies. Hullukin käy viisaasta, jos vaiti on; joka huulensa sulkee, on ymmärtäväinen.",
    "DAN.2.20-21": "Daniel lausui ja sanoi: \"Olkoon Jumalan nimi kiitetty iankaikkisesta iankaikkiseen, sillä hänen on viisaus ja voima. Hän muuttaa ajat ja hetket, hän syöksee kuninkaat vallasta ja korottaa kuninkaat valtaan, hän antaa viisaille viisauden ja taidollisille ymmärryksen.",
    "PRO.14.29": "Pitkämielisellä on paljon taitoa, mutta pikavihaisen osa on hulluus.",
    "JOB.28.28": "Ja ihmiselle hän sanoi: 'Katso, Herran pelko-se on viisautta, ja pahan karttaminen on ymmärrystä'.\"",
    "EPH.5.20": "kiittäen aina Jumalaa ja Isää kaikesta meidän Herramme Jeesuksen Kristuksen nimessä.",
    "PHP.4.6": "Älkää mistään murehtiko, vaan kaikessa saattakaa pyyntönne rukouksella ja anomisella kiitoksen kanssa Jumalalle tiettäväksi,",
    "PSA.95.1-2": "Tulkaa, kohottakaamme ilohuuto Herralle, riemuhuuto pelastuksemme kalliolle. Käykäämme kiittäen hänen kasvojensa eteen, veisatkaamme hänelle riemuvirsiä.",
    "PSA.9.1": "Minä ylistän Herraa kaikesta sydämestäni, ilmoitan kaikki sinun ihmetyösi.",
    "HEB.13.15": "Uhratkaamme siis hänen kauttansa Jumalalle joka aika kiitosuhria, se on: niiden huulten hedelmää, jotka hänen nimeänsä ylistävät.",
    "PSA.69.30": "niin minä veisuulla kiitän Jumalan nimeä ja ylistän häntä kiitosvirsillä.",
    "2CO.9.15": "Kiitos Jumalalle hänen sanomattomasta lahjastaan!",
    "PSA.106.1": "Halleluja! Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.",
    "PSA.92.1-2": "Hyvä on Herraa kiittää ja veisata kiitosta sinun nimellesi, sinä Korkein, aamulla julistaa sinun armoasi ja yön tullen sinun totuuttasi",
    "1TI.4.4-5": "Sillä kaikki, minkä Jumala on luonut, on hyvää, eikä mikään ole hyljättävää, kun se kiitoksella vastaanotetaan; sillä se pyhitetään Jumalan sanalla ja rukouksella.",
    "PSA.34.1": "Minä kiitän Herraa joka aika, hänen ylistyksensä on alati minun suussani.",
    "DAN.2.23": "Sinua, minun isieni Jumala, minä kiitän ja ylistän siitä, että olet antanut minulle viisauden ja voiman ja että nyt annoit minun tietää, mitä me sinulta rukoilimme. Sillä sinä annoit meidän tietää kuninkaan asian.\"",
    "COL.4.2": "Olkaa kestäväiset rukouksessa ja siinä kiittäen valvokaa,",
    "PSA.118.28-29": "Sinä olet minun Jumalani, ja sinua minä kiitän. Minun Jumalani, sinua minä kunnioitan. Kiittäkää Herraa, sillä hän on hyvä; sillä hänen armonsa pysyy iankaikkisesti.",
    "ISA.12.4-5": "Ja sinä päivänä te sanotte: \"Kiittäkää Herraa, julistakaa hänen nimeänsä, tehkää hänen suuret tekonsa tiettäviksi kansain keskuudessa, tunnustakaa, että hänen nimensä on korkea. Veisatkaa ylistystä Herralle, sillä jaloja töitä hän on tehnyt; tulkoot ne tunnetuiksi kaikessa maassa.",
    "PSA.145.1-3": "Minä kunnioitan sinua, Jumalani, sinä kuningas, ja kiitän sinun nimeäsi aina ja iankaikkisesti. Joka päivä minä kiitän sinua ja ylistän sinun nimeäsi aina ja iankaikkisesti. Suuri on Herra ja sangen ylistettävä, ja hänen suuruutensa on tutkimaton.",
    "1CO.15.57": "Mutta kiitos olkoon Jumalan, joka antaa meille voiton meidän Herramme Jeesuksen Kristuksen kautta!",
    "PSA.30.11-12": "Sinä muutit minun murheeni ilokarkeloksi, sinä riisuit minun surupukuni ja vyötit minut riemulla, että minun sieluni veisaisi sinulle kiitosta, eikä vaikenisi. Herra, minun Jumalani, sinua minä ylistän iankaikkisesti.",
    "REV.7.12": "sanoen: \"Amen! Ylistys ja kirkkaus ja viisaus ja kiitos ja kunnia ja voima ja väkevyys meidän Jumalallemme aina ja iankaikkisesti, amen!\"",
    "PSA.103.12": "Niin kaukana kuin itä on lännestä, niin kauas hän siirtää meistä rikkomuksemme.",
    "COL.3.13": "kärsikää toinen toistanne ja antakaa toisillenne anteeksi, jos kenellä on moitetta toista vastaan. Niinkuin Herrakin on antanut teille anteeksi, niin myös te antakaa.",
    "MAT.6.14-15": "Sillä jos te annatte anteeksi ihmisille heidän rikkomuksensa, niin teidän taivaallinen Isänne myös antaa teille anteeksi; mutta jos te ette anna ihmisille anteeksi, niin ei myöskään teidän Isänne anna anteeksi teidän rikkomuksianne.",
    "PSA.32.1-2": "Autuas se, jonka rikokset ovat anteeksi annetut, jonka synti on peitetty! Autuas se ihminen, jolle Herra ei lue hänen pahoja tekojansa ja jonka hengessä ei ole vilppiä!",
    "LUK.6.37": "Älkääkä tuomiko, niin ei teitäkään tuomita; älkää kadotustuomiota lausuko, niin ei teillekään kadotustuomiota lausuta. Antakaa anteeksi, niin teillekin anteeksi annetaan.",
    "ACT.3.19": "Tehkää siis parannus ja kääntykää, että teidän syntinne pyyhittäisiin pois,",
    "HEB.8.12": "Sillä minä annan anteeksi heidän vääryytensä enkä enää muista heidän syntejänsä.\"",
    "EPH.1.7": "jossa meillä on lunastus hänen verensä kautta, rikkomusten anteeksisaaminen, hänen armonsa rikkauden mukaan.",
    "ISA.43.25": "Minä, minä pyyhin pois sinun rikkomuksesi itseni tähden, enkä sinun syntejäsi muista.",
    "MRK.11.25": "Ja kun te seisotte ja rukoilette, niin antakaa anteeksi, jos kenellä teistä on jotakin toistansa vastaan, että myös teidän Isänne, joka on taivaissa, antaisi teille anteeksi teidän rikkomuksenne.\"",
    "PSA.51.1-2": "Jumala, ole minulle armollinen hyvyytesi tähden; pyyhi pois minun syntini suuren laupeutesi tähden. Pese minut puhtaaksi rikoksestani, puhdista minut synnistäni.",
    "LUK.23.34": "Mutta Jeesus sanoi: \"Isä, anna heille anteeksi, sillä he eivät tiedä, mitä he tekevät\". Ja he jakoivat keskenään hänen vaatteensa ja heittivät niistä arpaa.",
    "PSA.130.3-4": "Jos sinä, Herra, pidät mielessäsi synnit, Herra, kuka silloin kestää? Mutta sinun tykönäsi on anteeksiantamus, että sinua peljättäisiin.",
    "ROM.5.20": "Mutta laki tuli väliin, että rikkomus suureksi tulisi; mutta missä synti on suureksi tullut, siinä armo on tullut ylenpalttiseksi,",
    "MAT.18.21-22": "Silloin Pietari meni hänen tykönsä ja sanoi hänelle: \"Herra, kuinka monta kertaa minun on annettava anteeksi veljelleni, joka rikkoo minua vastaan? Ihanko seitsemän kertaa?\" Jeesus vastasi hänelle: \"Minä sanon sinulle: ei seitsemän kertaa, vaan seitsemänkymmentä kertaa seitsemän.",
    "HEB.4.16": "Käykäämme sentähden uskalluksella armon istuimen eteen, että saisimme laupeuden ja löytäisimme armon, avuksemme oikeaan aikaan.",
    "PRO.28.13": "Joka rikkomuksensa salaa, se ei menesty; mutta joka ne tunnustaa ja hylkää, se saa armon.",
    "ISA.55.7": "Jumalaton hyljätköön tiensä ja väärintekijä ajatuksensa ja palatkoon Herran tykö, niin hän armahtaa häntä, ja meidän Jumalamme tykö, sillä hänellä on paljon anteeksiantamusta.",
    "DAN.9.9": "Herran, meidän Jumalamme, on armo ja anteeksiantamus, sillä me olemme olleet hänelle uppiniskaiset;",
    "1TH.5.17": "Rukoilkaa lakkaamatta.",
    "MAT.6.6": "Vaan sinä, kun rukoilet, mene kammioosi ja sulje ovesi ja rukoile Isääsi, joka on salassa; ja sinun Isäsi, joka salassa näkee, maksaa sinulle.",
    "ROM.8.26": "Samoin myös Henki auttaa meidän heikkouttamme. Sillä me emme tiedä, mitä meidän pitää rukoileman, niinkuin rukoilla tulisi, mutta Henki itse rukoilee meidän puolestamme sanomattomilla huokauksilla.",
    "MAT.6.9-10": "Rukoilkaa siis te näin: Isä meidän, joka olet taivaissa! Pyhitetty olkoon sinun nimesi; tulkoon sinun valtakuntasi; tapahtukoon sinun tahtosi myös maan päällä niinkuin taivaassa;",
    "PSA.17.6": "Minä huudan sinua avukseni, sillä sinä vastaat minulle, Jumala; kallista korvasi minun puoleeni, kuule minun puheeni.",
    "LUK.11.9-10": "Niinpä minäkin sanon teille: anokaa, niin teille annetaan; etsikää, niin te löydätte; kolkuttakaa, niin teille avataan. Sillä jokainen anova saa, ja etsivä löytää, ja kolkuttavalle avataan.",
    "PSA.34.17": "Vanhurskaat huutavat, ja Herra kuulee ja vapahtaa heidät kaikista heidän ahdistuksistansa.",
    "EPH.6.18": "Ja tehkää tämä kaikella rukouksella ja anomisella, rukoillen joka aika Hengessä ja sitä varten valvoen kaikessa kestäväisyydessä ja anomisessa kaikkien pyhien puolesta;",
    "MAT.18.19-20": "Vielä minä sanon teille: jos kaksi teistä maan päällä keskenään sopii mistä asiasta tahansa, että he sitä anovat, niin he saavat sen minun Isältäni, joka on taivaissa. Sillä missä kaksi tahi kolme on kokoontunut minun nimeeni, siinä minä olen heidän keskellänsä.\"",
    "PSA.55.17": "Illoin, aamuin ja keskipäivällä minä valitan ja huokaan, ja hän kuulee minun ääneni.",
    "PSA.66.19-20": "Mutta Jumala kuuli minua ja otti vaarin minun rukoukseni äänestä. Kiitetty olkoon Jumala, joka ei hyljännyt minun rukoustani eikä ottanut minulta pois armoansa.",
    "MAT.26.41": "Valvokaa ja rukoilkaa, ettette joutuisi kiusaukseen; henki tosin on altis, mutta liha on heikko.\"",
    "PSA.5.3": "Herra, varhain sinä kuulet minun ääneni, varhain minä valmistan sinulle uhrin ja odotan.",
    "JHN.14.13-14": "ja mitä hyvänsä te anotte minun nimessäni, sen minä teen, että Isä kirkastettaisiin Pojassa. Jos te anotte minulta jotakin minun nimessäni, niin minä sen teen.",
    "JHN.15.7": "Jos te pysytte minussa ja minun sanani pysyvät teissä, niin anokaa, mitä ikinä tahdotte, ja te saatte sen.",
    "PSA.141.2": "Minun rukoukseni olkoon suitsutusuhri sinun kasvojesi edessä, minun kätteni kohottaminen olkoon ehtoouhri.",
    "1TI.2.1-2": "Minä kehoitan siis ennen kaikkea anomaan, rukoilemaan, pitämään esirukouksia ja kiittämään kaikkien ihmisten puolesta, kuningasten ja kaiken esivallan puolesta, että saisimme viettää rauhallista ja hiljaista elämää kaikessa jumalisuudessa ja kunniallisuudessa.",
    "LUK.18.1": "Ja hän puhui heille vertauksen siitä, että heidän tuli aina rukoilla eikä väsyä.",
    "PSA.102.17": "kun hän kääntyy niiden rukouksen puoleen, jotka ovat kaikkensa menettäneet, eikä enää heidän rukoustansa hylkää.",
    "JHN.15.11": "Tämän minä olen teille puhunut, että minun iloni olisi teissä ja teidän ilonne tulisi täydelliseksi.",
    "JAS.1.2-3": "Veljeni, pitäkää pelkkänä ilona, kun joudutte moninaisiin kiusauksiin, tietäen, että teidän uskonne kestäväisyys koetuksissa saa aikaan kärsivällisyyttä.",
    "PSA.126.5-6": "Jotka kyynelin kylvävät, ne riemuiten leikkaavat. He menevät itkien, kun kylvösiemenen vievät; he palajavat riemuiten, kun lyhteensä tuovat.",
    "1PE.1.8-9": "Häntä te rakastatte, vaikka ette ole häntä nähneet, häneen te uskotte, vaikka ette nyt häntä näe, ja riemuitsette sanomattomalla ja kirkastuneella ilolla, sillä te saavutatte uskon päämäärän, sielujen pelastuksen.",
    "PSA.5.11": "Ja iloitkoot kaikki, jotka sinuun turvaavat, ja riemuitkoot iankaikkisesti. Suojele heitä, että sinussa iloitsisivat ne, jotka rakastavat sinun nimeäsi.",
    "JHN.16.22": "Niin on myös teillä nyt murhe; mutta minä olen taas näkevä teidät, ja teidän sydämenne on iloitseva, eikä kukaan ota teiltä pois teidän iloanne.",
    "ISA.61.10": "Minä iloitsen suuresti Herrassa, minun sieluni riemuitsee minun Jumalassani, sillä hän pukee minun ylleni autuuden vaatteet ja verhoaa minut vanhurskauden viittaan, yljän kaltaiseksi, joka kantaa juhlapäähinettä niinkuin pappi, ja morsiamen kaltaiseksi, joka on koruillansa kaunistettu.",
    "PSA.100.1-2": "Kohottakaa riemuhuuto Herralle, kaikki maa. Palvelkaa Herraa ilolla, tulkaa hänen kasvojensa eteen riemulla.",
    "PSA.32.11": "Iloitkaa Herrassa ja riemuitkaa, te vanhurskaat, ja veisatkaa ilovirsiä, kaikki te oikeamieliset.",
    "1TH.5.16": "Olkaa aina iloiset.",
    "PSA.51.12": "Anna minulle jälleen autuutesi ilo, ja tue minua alttiuden hengellä.",
    "ISA.12.3": "Te saatte ilolla ammentaa vettä pelastuksen lähteistä.",
    "PSA.47.1": "Paukuttakaa käsiänne, kaikki kansat, kohottakaa Jumalalle riemuhuuto.",
    "LUK.15.10": "Niin myös, sanon minä teille, on ilo Jumalan enkeleillä yhdestä syntisestä, joka tekee parannuksen.\"",
    "PSA.97.11-12": "Vanhurskaalle koittaa valkeus ja oikeamielisille ilo. Iloitkaa Herrassa, te vanhurskaat; kiittäkää hänen pyhää nimeänsä.",
    "JHN.16.24": "Tähän asti te ette ole anoneet mitään minun nimessäni; anokaa, niin te saatte, että teidän ilonne olisi täydellinen."
};
